  `history_es` = IF(LOCATE(CAST('CLE lía en Danlí, con oficinas en Danlí, Estelí y Miami.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'CLE lía en Danlí, con oficinas en Danlí, Estelí y Miami.', 'CLE lía en Danlí, en una fábrica de la casa que Cigar Coop nombra «CLE Factory» en marzo de 2025 y Havano S.A. en septiembre de 2026.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('CLE rollt in Danlí, mit Büros in Danlí, Estelí und Miami.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'CLE rollt in Danlí, mit Büros in Danlí, Estelí und Miami.', 'CLE rollt in Danlí, in einer Fabrik des Hauses, die Cigar Coop im März 2025 „CLE Factory“ und im September 2026 Havano S.A. nennt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('CLE 在丹利卷制，并在丹利、埃斯特利与迈阿密设有办公室。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'CLE 在丹利卷制，并在丹利、埃斯特利与迈阿密设有办公室。', 'CLE 在丹利卷制，用的是该公司的一家工厂：Cigar Coop 在2025年3月称它为「CLE Factory」，在2026年9月则称它为 Havano S.A.。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تلفّ CLE في دانلي، ولها مكاتب في دانلي وإستيلي وميامي.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'تلفّ CLE في دانلي، ولها مكاتب في دانلي وإستيلي وميامي.', 'تلفّ CLE في دانلي، في مصنع تابع للدار تسمّيه Cigar Coop «CLE Factory» في آذار/مارس 2025، وHavano S.A. في أيلول/سبتمبر 2026.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'CLE Cigar Company';

UPDATE `brands` SET
  `factory` = 'Fabrique CLE (« CLE Factory » en mars 2025, Havano S.A. en septembre 2026, dit Cigar Coop), Danlí, Honduras',
  `source` = IF(LOCATE(CAST('cigar-coop.com « C.L.E. Cigar Company Releases Eiroa The Fir' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « C.L.E. Cigar Company Releases Eiroa The First 20 Years Redondo | Cigar News » (18 mars 2025 : production à la CLE Factory, Danlí, Honduras) ; cigar-coop.com « Leo Wijnbelt Joins CLE Team | Cigar News » (8 septembre 2026 : fabrique Havano S.A. de CLE Cigar Company à Danlí, expansion de la fabrique et des fermes) ; cigarsdirect.com « Buy CLE Cigars Online at Discount Prices and Save » (lue en octobre 2026, page de détaillant non datée, © 2026 : fabrique de Christian Eiroa à Danlí ; la fabrique d''Asylum est à Estelí) ; cigardojo.com « CLE Teases the Return of Wynwood Cigars » (13 septembre 2018 : l''usine de Miami, ouverte en 2012, a fermé une dizaine de mois plus tard)')),
  `updated_at` = NOW()
 WHERE `name` = 'CLE Cigar Company';

-- ── Foundation Cigar Company ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('El Güegüense, son assemblage fondateur, porte le nom d''une pièce de théâtre populaire nicaraguayenne' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'El Güegüense, son assemblage fondateur, porte le nom d''une pièce de théâtre populaire nicaraguayenne', 'El Güegüense, son assemblage fondateur de 2015, portait le nom d''une pièce de théâtre populaire nicaraguayenne'), `history`),
  `history_en` = IF(LOCATE(CAST('his founding blend, takes its name' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'his founding blend, takes its name', 'his founding blend of 2015, took its name'), `history_en`),
  `history_es` = IF(LOCATE(CAST('su liga fundacional, lleva el nombre' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'su liga fundacional, lleva el nombre', 'su liga fundacional de 2015, llevaba el nombre'), `history_es`),
  `history_de` = IF(LOCATE(CAST('sein Gründungsblend, trägt den Namen' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'sein Gründungsblend, trägt den Namen', 'sein Gründungsblend von 2015, trug den Namen'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('其奠基配方「厄尔·圭圭恩塞」得名于' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '其奠基配方「厄尔·圭圭恩塞」得名于', '其2015年的奠基配方「厄尔·圭圭恩塞」曾得名于'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('خلطته التأسيسية، فتحمل اسم' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'خلطته التأسيسية، فتحمل اسم', 'خلطته التأسيسية لعام 2015، فكانت تحمل اسم'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Foundation Cigar Company';

UPDATE `brands` SET
  `factory` = 'Tabacalera A.J. Fernandez, Estelí (Tabernacle, Highclere Castle, Charter Oak, Olmec, Aksum) ; My Father Cigars S.A., Estelí (The Wise Man depuis 2024) ; Nicaragua',
  `gamme` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"L''assemblage fondateur de 2015, nommé d''après une satire coloniale transmise oralement pendant des siècles, roulé alors à l''usine TABSA, aujourd''hui Aganorsa Leaf. En mars 2024, Foundation a annoncé l''arrêt d''El Güegüense, comme de l''ancien Wise Man Maduro, au profit de deux mélanges nouveaux, The Wise Man Corojo et Maduro, faits chez My Father Cigars. Il offrait bois, cuir, une pointe de sucre roux, et une évolution nette entre le premier et le dernier tiers.","vitolas":["Corona Gorda","Toro"],"wrapper":"Corojo 99 de Jalapa"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"La racine nord de la maison : cape du Connecticut sur tripe nicaraguayenne. Sombre, terreux, sans amertume — et volontairement placé dans une gamme de prix accessible.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — la ligne corsée, cape broadleaf, chez A.J. Fernández ; le recensement de cet atlas la prenait pour une maison.","vitolas":[],"wrapper":"Broadleaf du Connecticut"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — le château de Downton Abbey sur une bague, Connecticut d''Équateur.","vitolas":[],"wrapper":"Connecticut d''Équateur"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — un hommage au Mexique et à ses Olmèques, cape San Andrés, Claro et Maduro.","vitolas":[],"wrapper":"San Andrés (Mexique)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"Ancienne Metapa, rebaptisée en février 2024 pour une question de marque déposée, d''après Foundation, dont le fondateur écrit que le mélange reste le même ; Claro et Maduro, d''après Cigar Coop. Sous-cape Connecticut Broadleaf, tripe d''Estelí et de Jalapa, force annoncée de moyenne à corsée, en Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 et Doble Corona 7 x 54, roulée chez A.J. Fernández d''après Cigar Coop en avril 2024.","vitolas":[],"wrapper":"Sumatra d''Équateur"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"Présentée à l''IPCPR 2017 comme déclinaison Maduro d''El Güegüense, avec une cape San Andrés mexicaine ; refaite en 2024 chez My Father Cigars, avec la même cape sur une sous-cape d''Estelí et de Jalapa et une tripe d''Estelí, de Condega et de Jalapa. Force moyenne selon la maison, en Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 et Doble Corona 7 x 54, par vingt.","vitolas":[],"wrapper":"San Andrés (Mexique)"}]',
  `gamme_en` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"The founding blend of 2015, named after a colonial satire passed down orally for centuries, rolled at the time at the TABSA factory, today Aganorsa Leaf. In March 2024, Foundation announced the discontinuation of El Güegüense, as well as of the former Wise Man Maduro, in favour of two new blends, The Wise Man Corojo and Maduro, made at My Father Cigars. It offered wood, leather, a hint of brown sugar, and a clear evolution between the first and the last third.","vitolas":["Corona Gorda","Toro"],"wrapper":"Jalapa Corojo 99"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"The northern root of the house: Connecticut wrapper over Nicaraguan filler. Dark, earthy, without bitterness — and deliberately kept in an affordable price range.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — the full-bodied line, broadleaf wrapper, at A.J. Fernández; this atlas''s census took it for a house.","vitolas":[],"wrapper":"Connecticut broadleaf"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — the castle of Downton Abbey on a band, Ecuadorian Connecticut.","vitolas":[],"wrapper":"Ecuadorian Connecticut"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — a tribute to Mexico and its Olmecs, San Andrés wrapper, Claro and Maduro.","vitolas":[],"wrapper":"San Andrés (Mexico)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"Formerly Metapa, renamed in February 2024 over a trademark issue, according to Foundation, whose founder writes that the blend remains the same; Claro and Maduro, according to Cigar Coop. Connecticut Broadleaf binder, Estelí and Jalapa filler, strength stated as medium to full, in Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 and Doble Corona 7 x 54, rolled at A.J. Fernández according to Cigar Coop in April 2024.","vitolas":[],"wrapper":"Ecuadorian Sumatra"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"Presented at IPCPR 2017 as the Maduro variant of El Güegüense, with a Mexican San Andrés wrapper; remade in 2024 at My Father Cigars, with the same wrapper over a binder from Estelí and Jalapa and a filler from Estelí, Condega and Jalapa. Strength medium according to the company, in Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 and Doble Corona 7 x 54, twenty to a box.","vitolas":[],"wrapper":"San Andrés (Mexico)"}]',
  `gamme_es` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"La liga fundacional de 2015, con el nombre de una sátira colonial transmitida oralmente durante siglos, liada entonces en la fábrica TABSA, hoy Aganorsa Leaf. En marzo de 2024, Foundation anunció el cese de El Güegüense, así como del antiguo Wise Man Maduro, en favor de dos mezclas nuevas, The Wise Man Corojo y Maduro, hechas en My Father Cigars. Ofrecía madera, cuero, una pizca de azúcar moreno, y una evolución neta entre el primer y el último tercio.","vitolas":["Corona Gorda","Toro"],"wrapper":"Corojo 99 de Jalapa"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"La raíz norte de la casa: capa del Connecticut sobre tripa nicaragüense. Oscuro, terroso, sin amargor — y situado a propósito en una gama de precios accesible.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — la línea fuerte, capa broadleaf, en A.J. Fernández; el censo de este atlas la tomaba por una casa.","vitolas":[],"wrapper":"Broadleaf de Connecticut"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — el castillo de Downton Abbey en una anilla, Connecticut de Ecuador.","vitolas":[],"wrapper":"Connecticut de Ecuador"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — un homenaje a México y a sus olmecas, capa San Andrés, Claro y Maduro.","vitolas":[],"wrapper":"San Andrés (México)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"Antigua Metapa, rebautizada en febrero de 2024 por una cuestión de marca registrada, según Foundation, cuyo fundador escribe que la mezcla sigue siendo la misma; Claro y Maduro, según Cigar Coop. Capote Connecticut Broadleaf, tripa de Estelí y de Jalapa, fuerza anunciada de medium a fuerte, en Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 y Doble Corona 7 x 54, enrollada en A.J. Fernández según Cigar Coop en abril de 2024.","vitolas":[],"wrapper":"Sumatra de Ecuador"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"Presentada en el IPCPR 2017 como variante Maduro de El Güegüense, con una capa San Andrés mexicana; rehecha en 2024 en My Father Cigars, con la misma capa sobre un capote de Estelí y de Jalapa y una tripa de Estelí, de Condega y de Jalapa. Fuerza medium según la casa, en Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 y Doble Corona 7 x 54, veinte por caja.","vitolas":[],"wrapper":"San Andrés (México)"}]',
  `gamme_de` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"Der Gründungsblend von 2015, benannt nach einer kolonialen Satire, die über Jahrhunderte mündlich überliefert wurde, damals in der Fabrik TABSA gerollt, heute Aganorsa Leaf. Im März 2024 kündigte Foundation die Einstellung von El Güegüense an, ebenso wie die des früheren Wise Man Maduro, zugunsten zweier neuer Blends, The Wise Man Corojo und Maduro, hergestellt bei My Father Cigars. Er bot Holz, Leder, einen Anflug von braunem Zucker und eine klare Entwicklung zwischen erstem und letztem Drittel.","vitolas":["Corona Gorda","Toro"],"wrapper":"Corojo 99 aus Jalapa"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"Die nördliche Wurzel des Hauses: Connecticut-Deckblatt über nicaraguanischer Einlage. Dunkel, erdig, ohne Bitterkeit — und bewusst in einer erschwinglichen Preislage gehalten.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — die kräftige Linie, Broadleaf-Deckblatt, bei A.J. Fernández; die Zählung dieses Atlas hielt sie für ein Haus.","vitolas":[],"wrapper":"Connecticut-Broadleaf"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — das Schloss von Downton Abbey auf einer Bauchbinde, ecuadorianisches Connecticut.","vitolas":[],"wrapper":"Ecuadorianisches Connecticut"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — eine Hommage an Mexiko und seine Olmeken, San-Andrés-Deckblatt, Claro und Maduro.","vitolas":[],"wrapper":"San Andrés (Mexiko)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"Frühere Metapa, im Februar 2024 wegen einer Markenrechtsfrage umbenannt, laut Foundation, deren Gründer schreibt, dass die Mischung dieselbe bleibt; Claro und Maduro, laut Cigar Coop. Umblatt Connecticut Broadleaf, Einlage aus Estelí und Jalapa, angegebene Stärke von medium bis kräftig, in Robusto 5 x 50, Corona Gorda 5½ x 48, Toro 6 x 52 und Doble Corona 7 x 54, laut Cigar Coop im April 2024 bei A.J. Fernández gerollt.","vitolas":[],"wrapper":"Sumatra aus Ecuador"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"Auf der IPCPR 2017 als Maduro-Variante von El Güegüense vorgestellt, mit einem mexikanischen Deckblatt San Andrés; 2024 bei My Father Cigars neu gefertigt, mit demselben Deckblatt über einem Umblatt aus Estelí und Jalapa und einer Einlage aus Estelí, Condega und Jalapa. Stärke medium laut Haus, in Corona 5 x 48, Robusto 5½ x 50, Toro 6 x 52 und Doble Corona 7 x 54, zu je zwanzig in der Schachtel.","vitolas":[],"wrapper":"San Andrés (Mexiko)"}]',
  `gamme_zh` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"2015年的奠基配方，得名于一出口传数百年的殖民时期讽刺剧，当时在 TABSA 工厂卷制，该厂如今是 Aganorsa Leaf。2024年3月，Foundation 宣布停产 El Güegüense，连同此前的 Wise Man Maduro，改以两款新配方 The Wise Man Corojo 与 Maduro 取代，由 My Father Cigars 制作。它有木质、皮革，一丝红糖，从首段到末段有清晰的推进。","vitolas":["Corona Gorda","Toro"],"wrapper":"哈拉帕可乐多99"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"这家的北方之根：康涅狄格茄衣配尼加拉瓜茄芯。深色、带土味、不苦——并有意保持在可及的价位。","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016年——浓烈的一线，broadleaf 茄衣，在 A.J. Fernández 制作；本图集的普查曾把它当作一家公司。","vitolas":[],"wrapper":"康涅狄格 broadleaf"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017年——茄标上的唐顿庄园城堡，厄瓜多尔康涅狄格茄衣。","vitolas":[],"wrapper":"厄瓜多尔康涅狄格"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"2022年 PCA——向墨西哥及其奥尔梅克人致敬，圣安德烈斯茄衣，Claro 与 Maduro。","vitolas":[],"wrapper":"圣安德烈斯（墨西哥）"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"前身为Metapa，2024年二月因商标问题更名，据Foundation所述，其创始人写道，拼配保持不变；据Cigar Coop，为Claro和Maduro。茄套为Connecticut Broadleaf，茄芯来自Estelí和Jalapa，标称烟力为medium至浓郁，规格为Robusto 5 x 50、Corona Gorda 5½ x 48、Toro 6 x 52和Doble Corona 7 x 54，据Cigar Coop于2024年四月所述，在A.J. Fernández卷制。","vitolas":[],"wrapper":"厄瓜多尔Sumatra"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"在IPCPR 2017上作为El Güegüense的Maduro版本亮相，采用墨西哥San Andrés茄衣；2024年在My Father Cigars重新制作，茄衣相同，茄套取自Estelí和Jalapa，茄芯取自Estelí、Condega和Jalapa。据该公司，烟力为medium，规格为Corona 5 x 48、Robusto 5½ x 50、Toro 6 x 52和Doble Corona 7 x 54，每盒二十支。","vitolas":[],"wrapper":"San Andrés（墨西哥）"}]',
  `gamme_ar` = '[{"name":"El Güegüense","color":"#8B4513","force":"Medium","story":"الخلطة التأسيسية لعام 2015، التي تحمل اسم هجائية استعمارية تناقلتها الأفواه قروناً، وكانت تُلفّ حينذاك في مصنع TABSA، وهو اليوم Aganorsa Leaf. وفي آذار/مارس 2024 أعلنت Foundation وقف إنتاج El Güegüense، وكذلك وقف إنتاج Wise Man Maduro السابق، لصالح خلطتين جديدتين، The Wise Man Corojo وMaduro، تُصنعان لدى My Father Cigars. وكانت تقدّم خشبًا وجلدًا ولمسة سكر بنّي، مع تطوّر واضح بين الثلث الأول والأخير.","vitolas":["Corona Gorda","Toro"],"wrapper":"كوروخو 99 من خالابا"},{"name":"Charter Oak","color":"#3B2F2F","force":"Medium","story":"الجذر الشمالي للدار: غلاف كونيتيكت على حشوة نيكاراغوية. داكن، ترابي، بلا مرارة — وموضوع عمداً في نطاق سعري في المتناول.","vitolas":["Robusto"],"wrapper":"Connecticut Broadleaf"},{"name":"The Tabernacle","color":"#3A2A1E","force":"Full","story":"2016 — الخطّ القويّ، غلاف برودليف، لدى A.J. Fernández؛ وكان إحصاء هذا الأطلس يحسبه دارًا.","vitolas":[],"wrapper":"برودليف كونيتيكت"},{"name":"Highclere Castle","color":"#C9A96E","force":"Mild-Medium","story":"2017 — قصر داونتون آبي على حزام، كونيتيكت إكوادوري.","vitolas":[],"wrapper":"كونيتيكت إكوادوري"},{"name":"Olmec","color":"#6B4226","force":"Medium-Full","story":"PCA 2022 — تحيّة للمكسيك وأولميكها، غلاف سان أندريس، Claro وMaduro.","vitolas":[],"wrapper":"سان أندريس (المكسيك)"},{"name":"Aksum","color":"#8B5A2B","force":"Medium-Full","story":"كان سابقًا Metapa، وأُعيدت تسميته في فبراير 2024 لمسألة تتعلق بالعلامة التجارية المسجّلة، بحسب Foundation التي يكتب مؤسسها أن التوليفة تبقى نفسها؛ Claro وMaduro، بحسب Cigar Coop. رابط Connecticut Broadleaf، وحشوة من Estelí وJalapa، وقوة معلنة بين medium وقوية، بمقاسات Robusto 5 x 50 وCorona Gorda 5½ x 48 وToro 6 x 52 وDoble Corona 7 x 54، يُلَفّ لدى A.J. Fernández بحسب Cigar Coop في أبريل 2024.","vitolas":[],"wrapper":"Sumatra من الإكوادور"},{"name":"The Wise Man Maduro","color":"#4A3728","force":"Medium","story":"قُدّم في IPCPR 2017 بوصفه النسخة Maduro من El Güegüense، بغلاف خارجي San Andrés مكسيكي؛ وأُعيد صنعه في 2024 لدى My Father Cigars، بالغلاف نفسه فوق رابط من Estelí وJalapa وحشوة من Estelí وCondega وJalapa. قوة medium بحسب الشركة، بمقاسات Corona 5 x 48 وRobusto 5½ x 50 وToro 6 x 52 وDoble Corona 7 x 54، بواقع عشرين في العلبة.","vitolas":[],"wrapper":"San Andrés (المكسيك)"}]',
  `source` = IF(LOCATE(CAST('(2015, les dix ans chez Drew Estate, El Güegüense, production chez A.J. Fernández)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, '(2015, les dix ans chez Drew Estate, El Güegüense, production chez A.J. Fernández)', '(numéro du 20 février 2018 : les dix ans chez Drew Estate, El Güegüense ; l''entretien n''attribue pas la production d''El Güegüense à A.J. Fernández)'), `source`),
  `source` = IF(LOCATE(CAST('cigaraficionado.com « Foundation Cigar Co. Unveils Its First' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigaraficionado.com « Foundation Cigar Co. Unveils Its First Brand » (9 juillet 2015 : El Güegüense faite à l''usine TABSA, Nicaragua, cape et liant Corojo ''99 de Jalapa) ; cigaraficionado.com « Foundation Cigar Co. » (page de société lue en octobre 2026, non datée : les deux El Güegüense faits à TABSA, les deux autres marques de l''époque à la Tabacalera A.J. Fernandez) ; cigar-coop.com « Cigar News: Foundation Cigar Company Announces Tabernacle » (13 juillet 2016 : Tabacalera Fernandez ; El Güegüense hors de l''installation TABSA de Casa Fernandez) ; smokingpipes.com « Smoke Rings: Foundation Cigar Company » (3 mars 2020, blog de détaillant : presque tout à Tabsa, Aganorsa, sauf The Tabernacle faite par AJ Fernandez) ; cigaraficionado.com « Foundation Discontinues El Güegüense, Introduces Wise Man Corojo And Maduro With My Father Cigars » (11 mars 2024 : lignes d''origine à Aganorsa Leaf, anciennement TABSA ; nouveaux mélanges chez My Father, usine des Garcia à Estelí) ; cigardojo.com « Foundation Cigars Re-Introduces Wise Man Line Taps My Father Cigars for Production » (12 mars 2024) ; cigar-coop.com « Cigar News: Foundation Cigar Company to Introduce Olmec at 2022 PCA Trade Show » (1er juillet 2022 : Olmec à la Tabacalera AJ Fernandez) ; cigaraficionado.com « Two New Charter Oaks From Foundation Coming This Fall » (14 juin 2023 : Charter Oak faites par A.J. Fernandez) ; cigar-coop.com « PCA 2025: Foundation Cigar Company » (27 avril 2025) et « PCA 2026: Foundation Cigars » (26 avril 2026 : l''usine AJ Fernandez, principal partenaire de production de Foundation)')),
  `updated_at` = NOW()
 WHERE `name` = 'Foundation Cigar Company';

-- ── General Cigar ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Le Scandinavian Tobacco Group, qui a racheté General Cigar en 2016, y a ajouté' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Le Scandinavian Tobacco Group, qui a racheté General Cigar en 2016, y a ajouté', 'Le Scandinavian Tobacco Group, issu en 2010 de la réunion de ses activités cigares avec celles de Swedish Match, propriétaire de General Cigar depuis 2005, et coté en Bourse depuis 2016, y a ajouté'), `history`),
  `history_en` = IF(LOCATE(CAST('The Scandinavian Tobacco Group, which acquired General Cigar in 2016, added' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The Scandinavian Tobacco Group, which acquired General Cigar in 2016, added', 'The Scandinavian Tobacco Group, formed in 2010 by the merger of its cigar activities with those of Swedish Match, owner of General Cigar since 2005, and listed on the stock exchange since 2016, added'), `history_en`),
  `history_es` = IF(LOCATE(CAST('El Scandinavian Tobacco Group, que compró General Cigar en 2016, le añadió' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'El Scandinavian Tobacco Group, que compró General Cigar en 2016, le añadió', 'El Scandinavian Tobacco Group, surgido en 2010 de la reunión de sus actividades de puros con las de Swedish Match, propietaria de General Cigar desde 2005, y que cotiza en bolsa desde 2016, le añadió'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Die Scandinavian Tobacco Group, die General Cigar 2016 übernahm, brachte' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Die Scandinavian Tobacco Group, die General Cigar 2016 übernahm, brachte', 'Die Scandinavian Tobacco Group, 2010 durch die Zusammenlegung ihrer Zigarrenaktivitäten mit denen von Swedish Match, Eigentümerin von General Cigar seit 2005, entstanden und seit 2016 börsennotiert, brachte'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('2016年收购 General Cigar 的 Scandinavian Tobacco Group，' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '2016年收购 General Cigar 的 Scandinavian Tobacco Group，', '2010年由其雪茄业务与 Swedish Match 的雪茄业务合并而成（Swedish Match 自2005年起拥有 General Cigar）、自2016年起在证券交易所上市的 Scandinavian Tobacco Group，'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('«سكانديناڤيان توباكو غروب»، التي اشترت «جنرال سيغار» عام 2016،' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '«سكانديناڤيان توباكو غروب»، التي اشترت «جنرال سيغار» عام 2016،', 'Scandinavian Tobacco Group، التي نشأت عام 2010 من ضمّ أنشطتها في السيجار إلى أنشطة Swedish Match، مالكة General Cigar منذ 2005، والمدرجة في البورصة منذ 2016،'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'General Cigar';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('en position défavorable.' AS BINARY), CAST(`history` AS BINARY)) > 0 AND LOCATE(CAST('en position défavorable. En janvier 2026, il a confié à l''équipe de vente de Forged Cigar Company les marques Cohiba (non cubaine), Punch et Havana Honeys, jusque-là vendues par celle de General Cigar, et lui a rendu Partagás et Room101 ; la fabrication ne change pas, dit Cigar Coop.' AS BINARY), CAST(`history` AS BINARY)) = 0, REPLACE(`history`, 'en position défavorable.', 'en position défavorable. En janvier 2026, il a confié à l''équipe de vente de Forged Cigar Company les marques Cohiba (non cubaine), Punch et Havana Honeys, jusque-là vendues par celle de General Cigar, et lui a rendu Partagás et Room101 ; la fabrication ne change pas, dit Cigar Coop.'), `history`),
  `history_en` = IF(LOCATE(CAST('operated at a disadvantage.' AS BINARY), CAST(`history_en` AS BINARY)) > 0 AND LOCATE(CAST('operated at a disadvantage. In January 2026, the group entrusted to the sales team of Forged Cigar Company the Cohiba (non-Cuban), Punch and Havana Honeys brands, until then sold by that of General Cigar, and returned Partagás and Room101 to the latter; manufacturing does not change, says Cigar Coop.' AS BINARY), CAST(`history_en` AS BINARY)) = 0, REPLACE(`history_en`, 'operated at a disadvantage.', 'operated at a disadvantage. In January 2026, the group entrusted to the sales team of Forged Cigar Company the Cohiba (non-Cuban), Punch and Havana Honeys brands, until then sold by that of General Cigar, and returned Partagás and Room101 to the latter; manufacturing does not change, says Cigar Coop.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('en posición desfavorable.' AS BINARY), CAST(`history_es` AS BINARY)) > 0 AND LOCATE(CAST('en posición desfavorable. En enero de 2026, el grupo confió al equipo de ventas de Forged Cigar Company las marcas Cohiba (no cubana), Punch y Havana Honeys, hasta entonces vendidas por el de General Cigar, y devolvió a este último Partagás y Room101; la fabricación no cambia, dice Cigar Coop.' AS BINARY), CAST(`history_es` AS BINARY)) = 0, REPLACE(`history_es`, 'en posición desfavorable.', 'en posición desfavorable. En enero de 2026, el grupo confió al equipo de ventas de Forged Cigar Company las marcas Cohiba (no cubana), Punch y Havana Honeys, hasta entonces vendidas por el de General Cigar, y devolvió a este último Partagás y Room101; la fabricación no cambia, dice Cigar Coop.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('im Nachteil arbeiteten.' AS BINARY), CAST(`history_de` AS BINARY)) > 0 AND LOCATE(CAST('im Nachteil arbeiteten. Im Januar 2026 vertraute der Konzern dem Vertriebsteam von Forged Cigar Company die Marken Cohiba (nichtkubanisch), Punch und Havana Honeys an, die bis dahin vom Team von General Cigar verkauft wurden, und gab diesem Partagás und Room101 zurück; die Fertigung ändert sich nicht, sagt Cigar Coop.' AS BINARY), CAST(`history_de` AS BINARY)) = 0, REPLACE(`history_de`, 'im Nachteil arbeiteten.', 'im Nachteil arbeiteten. Im Januar 2026 vertraute der Konzern dem Vertriebsteam von Forged Cigar Company die Marken Cohiba (nichtkubanisch), Punch und Havana Honeys an, die bis dahin vom Team von General Cigar verkauft wurden, und gab diesem Partagás und Room101 zurück; die Fertigung ändert sich nicht, sagt Cigar Coop.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('处于不利位置的市场。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0 AND LOCATE(CAST('处于不利位置的市场。2026年1月，该集团把 Cohiba（非古巴）、Punch 与 Havana Honeys 这些品牌交给 Forged Cigar Company 的销售团队，它们此前由 General Cigar 的销售团队销售；并把 Partagás 与 Room101 交还给后者；制造不变，据 Cigar Coop 称。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0, REPLACE(`history_zh`, '处于不利位置的市场。', '处于不利位置的市场。2026年1月，该集团把 Cohiba（非古巴）、Punch 与 Havana Honeys 这些品牌交给 Forged Cigar Company 的销售团队，它们此前由 General Cigar 的销售团队销售；并把 Partagás 与 Room101 交还给后者；制造不变，据 Cigar Coop 称。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('من موقع غير مؤاتٍ.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0 AND LOCATE(CAST('من موقع غير مؤاتٍ. وفي كانون الثاني/يناير 2026 أوكلت المجموعة إلى فريق مبيعات Forged Cigar Company علامات Cohiba (غير الكوبية) وPunch وHavana Honeys، التي كان يبيعها حتى ذلك الحين فريق General Cigar، وأعادت إليه Partagás وRoom101؛ ولا يتغيّر التصنيع، بحسب Cigar Coop.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0, REPLACE(`history_ar`, 'من موقع غير مؤاتٍ.', 'من موقع غير مؤاتٍ. وفي كانون الثاني/يناير 2026 أوكلت المجموعة إلى فريق مبيعات Forged Cigar Company علامات Cohiba (غير الكوبية) وPunch وHavana Honeys، التي كان يبيعها حتى ذلك الحين فريق General Cigar، وأعادت إليه Partagás وRoom101؛ ولا يتغيّر التصنيع، بحسب Cigar Coop.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'General Cigar';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('ou une Cohiba Blue' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'ou une Cohiba Blue', 'ou une Hoyo de Monterrey non cubaine'), `history`),
  `history_es` = IF(LOCATE(CAST('o una Cohiba Blue' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'o una Cohiba Blue', 'o una Hoyo de Monterrey no cubana'), `history_es`),
  `history_de` = IF(LOCATE(CAST('oder eine Cohiba Blue' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'oder eine Cohiba Blue', 'oder eine nichtkubanische Hoyo de Monterrey'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('一支 Cohiba Blue' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '一支 Cohiba Blue', '一支非古巴的 Hoyo de Monterrey'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أو «كوهيبا بلو»' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أو «كوهيبا بلو»', 'أو «Hoyo de Monterrey» غير الكوبي'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'General Cigar';

UPDATE `brands` SET
  `gamme` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"La gamme la plus vendue de la maison aux États-Unis. Cape Connecticut Shade, douce et crémeuse, sur assemblage dominicain et jamaïcain. Notes de crème, cèdre léger, noisette. Format Café Baron de Rothschild (42 x 127mm). Le cigare des terrasses ensoleillées et des après-midi sans urgence.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Série inspirée des moteurs Harley-Davidson V-twin, aux formats nommés d''après des pièces : V660 Carb, V554 Piston, V770 Engine. Cape d''Équateur sur nicaraguayen et hondurien. Corsée, notes de cuir, café noir, chocolat. Cigare de route et d''Amérique profonde.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Équateur"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"Le portefeuille de la famille Toraño, racheté en septembre 2014 — les marques seulement ; la société Toraño Family Cigar a cessé, et Charlie Toraño est resté consultant. Carlos Toraño est mort en février 2022. L''atlas avait supprimé un « Carlos Toraño Panama » inventé (204) ; la marque Toraño, elle, est réelle et vit ici.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"Marque de bundles à petit prix présentée par General Cigar à l''IPCPR 2016, d''origine Nicaragua, avec un Habano (cape habano nicaraguayenne) et un Connecticut (cape Connecticut Shade du Honduras) ; six déclinaisons en 2025, dont Full (septembre 2021), roulée à la main à STG Estelí. Depuis le 1er août 2025, STG la confie à l''équipe de vente de Forged Cigar Company, sans changement de produit.","vitolas":[],"wrapper":"Non divulguée"}]',
  `gamme_en` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"America''s best-seller for 30 years. Connecticut Shade wrapper, soft and creamy, over Dominican-Jamaican blend. Notes of cream, light cedar, hazelnut. The cigar of sunny terraces and unhurried afternoons. Consistent, accessible, never disappointing.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Series inspired by Harley-Davidson V-twin engines. Format names: V660 Carb, V554 Piston, V770 Engine. Ecuadorian wrapper over Nicaraguan-Honduran. Full body, notes of motorcycle leather, black coffee, chocolate, engine oil (really). A cigar of the open road, freedom, deep America.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuadorian"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"The Toraño family''s portfolio, bought in September 2014 — the brands only; the Toraño Family Cigar company ceased, and Charlie Toraño stayed on as a consultant. Carlos Toraño died in February 2022. This atlas had deleted an invented \\"Carlos Toraño Panama\\" (204); the Toraño brand itself is real and lives here.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"Brand of low-priced bundles presented by General Cigar at IPCPR 2016, of Nicaraguan origin, with a Habano (Nicaraguan habano wrapper) and a Connecticut (Honduran Connecticut Shade wrapper); six variants in 2025, including Full (September 2021), hand-rolled at STG Estelí. Since 1 August 2025, STG has entrusted it to the sales team of Forged Cigar Company, with no change to the product.","vitolas":[],"wrapper":"Undisclosed"}]',
  `gamme_es` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"El superventas estadounidense desde hace treinta años. Capa Connecticut Shade suave y cremosa sobre liga dominicano-jamaicana. Crema, cedro ligero, avellana. Formato Café Baron de Rothschild (42 x 127mm). El puro de las terrazas soleadas y de las tardes sin prisa. Regular, accesible, nunca decepciona.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Serie inspirada en los motores V-twin de Harley-Davidson, con formatos bautizados como piezas: V660 Carb, V554 Piston, V770 Engine. Capa de Ecuador sobre tripa nicaragüense y hondureña. Potente, con notas de cuero, café negro y chocolate. Un puro de carretera y de la América profunda.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuador"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"El portafolio de la familia Toraño, comprado en septiembre de 2014 — solo las marcas; la sociedad Toraño Family Cigar cesó, y Charlie Toraño quedó como consultor. Carlos Toraño murió en febrero de 2022. Este atlas había suprimido un «Carlos Toraño Panamá» inventado (204); la marca Toraño, en cambio, es real y vive aquí.","vitolas":[],"wrapper":"No divulgada"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"Marca de bundles de precio bajo presentada por General Cigar en el IPCPR 2016, de origen Nicaragua, con un Habano (capa habano nicaragüense) y un Connecticut (capa Connecticut Shade de Honduras); seis variantes en 2025, entre ellas Full (septiembre de 2021), enrollada a mano en STG Estelí. Desde el 1 de agosto de 2025, STG la confía al equipo de ventas de Forged Cigar Company, sin cambio de producto.","vitolas":[],"wrapper":"No divulgada"}]',
  `gamme_de` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"Der amerikanische Bestseller seit dreißig Jahren. Mildes, cremiges Connecticut-Shade-Deckblatt über dominikanisch-jamaikanischer Mischung. Sahne, leichte Zeder, Haselnuss. Format Café Baron de Rothschild (42 x 127 mm). Die Zigarre für sonnige Terrassen und Nachmittage ohne Eile. Gleichmäßig, zugänglich, nie enttäuschend.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"Eine Serie, inspiriert von den V-Twin-Motoren von Harley-Davidson, mit Formaten, die wie Bauteile heißen: V660 Carb, V554 Piston, V770 Engine. Deckblatt aus Ecuador über nicaraguanischer und honduranischer Einlage. Kräftig, mit Noten von Leder, schwarzem Kaffee und Schokolade. Eine Zigarre der Landstraße und des tiefen Amerika.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"Ecuador"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"Das Portfolio der Familie Toraño, im September 2014 gekauft — nur die Marken; die Gesellschaft Toraño Family Cigar hörte auf, und Charlie Toraño blieb Berater. Carlos Toraño starb im Februar 2022. Dieser Atlas hatte ein erfundenes „Carlos Toraño Panama“ gelöscht (204); die Marke Toraño selbst ist real und lebt hier.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"Marke von bundles zu niedrigem Preis, von General Cigar auf der IPCPR 2016 vorgestellt, Herkunft Nicaragua, mit einem Habano (nicaraguanisches Habano-Deckblatt) und einem Connecticut (Deckblatt Connecticut Shade aus Honduras); sechs Varianten im Jahr 2025, darunter Full (September 2021), von Hand gerollt bei STG Estelí. Seit dem 1. August 2025 vertraut STG sie dem Vertriebsteam von Forged Cigar Company an, ohne Änderung am Produkt.","vitolas":[],"wrapper":"Nicht angegeben"}]',
  `gamme_zh` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"三十年来的美国畅销之作。柔和奶油般的康涅狄格阴植茄衣，内裹多米尼加与牙买加配方。奶油、轻盈雪松、榛子。Café Baron de Rothschild 规格（42 x 127 毫米）。这是阳光露台与不赶时间的午后的雪茄。稳定、平易，从不让人失望。","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"这一系列取材于哈雷戴维森的 V-twin 发动机，各规格以零件命名：V660 Carb、V554 Piston、V770 Engine。厄瓜多尔茄衣，包裹尼加拉瓜与洪都拉斯茄芯。风格厚重，带皮革、黑咖啡与巧克力的气息——属于公路与美国腹地的一支雪茄。","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"厄瓜多尔"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"托拉尼奥家族的品牌组合，2014年9月买下——只有品牌；Toraño Family Cigar 公司停业，查理·托拉尼奥留任顾问。卡洛斯·托拉尼奥2022年2月去世。本图集曾删除一个杜撰的「Carlos Toraño Panama」（204）；Toraño 品牌本身是真实的，在这里延续。","vitolas":[],"wrapper":"未公开"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"低价位bundles品牌，由General Cigar在IPCPR 2016上亮相，原产国为尼加拉瓜，包含Habano版（尼加拉瓜habano茄衣）与Connecticut版（洪都拉斯Connecticut Shade茄衣）；2025年共有六个版本，其中包括Full（2021年九月），在STG Estelí手工卷制。自2025年八月1日起，STG将其交由Forged Cigar Company的销售团队负责，产品不变。","vitolas":[],"wrapper":"未公开"}]',
  `gamme_ar` = '[{"name":"Macanudo Café","color":"#C9A96E","force":"Light-Medium","story":"الأكثر مبيعًا في أمريكا منذ ثلاثين عامًا. غلاف كونيتيكت شيد لطيف وقشديّ فوق خلطة دومينيكية-جامايكية. قشدة، أرز خفيف، بندق. قياس كافيه بارون دي روتشيلد (42 × 127 مم). سيجار الشرفات المشمسة والأصائل بلا عجلة. منتظم، سهل المنال، لا يخيّب.","vitolas":["Café","Baron de Rothschild","Hyde Park","Hampton Court","Prince Philip"],"wrapper":"Connecticut Shade"},{"name":"CAO Flathead","color":"#8B4513","force":"Full","story":"سلسلة مستوحاة من محرّكات هارلي ديفيدسون ثنائية الأسطوانة، بقياسات تحمل أسماء قطع المحرّك: V660 Carb وV554 Piston وV770 Engine. غلافة من الإكوادور فوق حشوة نيكاراغوية وهندوراسية. قوية، بنكهات الجلد والقهوة السوداء والشوكولاتة — سيجارة الطريق وأمريكا العميقة.","vitolas":["V660 Carb","V554 Piston","V770 Engine","V507 Spark"],"wrapper":"إكوادوري"},{"name":"Toraño","color":"#8B3A1E","force":"Medium-Full","story":"محفظة عائلة تورانيو، اشتُريت في أيلول/سبتمبر 2014 — العلامات فقط؛ توقّفت شركة Toraño Family Cigar، وبقي تشارلي تورانيو مستشارًا. وتوفّي كارلوس تورانيو في شباط/فبراير 2022. كان هذا الأطلس قد حذف «Carlos Toraño Panama» مختلَقًا (204)؛ أمّا علامة Toraño فحقيقية وتعيش هنا.","vitolas":[],"wrapper":"غير معلن"},{"name":"Odyssey","color":"#8B5A2B","force":null,"story":"علامة bundles منخفضة السعر قدّمتها General Cigar في IPCPR 2016، بلد المنشأ نيكاراغوا، تضم Habano (غلاف خارجي habano نيكاراغوي) وConnecticut (غلاف خارجي Connecticut Shade من هندوراس)؛ ست نسخ في 2025، منها Full (سبتمبر 2021)، تُلَفّ يدويًا في STG Estelí. ومنذ 1 أغسطس 2025 تُسندها STG إلى فريق المبيعات في Forged Cigar Company، دون تغيير في المنتج.","vitolas":[],"wrapper":"غير معلن"}]',
  `source` = IF(LOCATE(CAST('propriété de Scandinavian Tobacco Group depuis 2005' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'propriété de Scandinavian Tobacco Group depuis 2005', 'propriété de Swedish Match depuis 2005, puis du Scandinavian Tobacco Group depuis la réunion de 2010'), `source`),
  `source` = IF(LOCATE(CAST('cigar-coop.com « STG Moving Cohiba and Punch Brands to Forge' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « STG Moving Cohiba and Punch Brands to Forged while shifting Room101 and Partagas to General | Cigar News » (14 janvier 2026 : Cohiba, Punch et Havana Honeys passent de General à Forged, Partagas et Room101 de Forged à General ; raison donnée aux détaillants : organisation des ventes plus équilibrée) ; cigar-coop.com « General Cigar Dominicana | Procigar 2026 » (24 février 2026 : la scission est une affaire de vente et de distribution, General Cigar Dominicana et les deux autres usines produisent pour General et pour Forged, production inchangée pour Cohiba) ; cigar-coop.com « Forged Cigar Company Announces Mr. Punch by Punch Cigar | Cigar News » (30 juin 2026 : Punch non cubaine possédée par STG, parent de Forged ; Mr. Punch faite à l''usine STG d''Estelí) ; cigaraficionado.com « Mr. Punch Gets Its Own Punch Line » (1er juillet 2026 : les Punch non cubaines sont distribuées par Forged Cigar Co., filiale de STG) ; stogiereview.com « Punch Upper Cut Robusto » (9 décembre 2009) et kohnhed.com « Punch Uppercut | Cigar Review » (19 août 2014 : Upper Cut, cape Sumatra d''Équateur, tripe nicaraguayenne, faite au Honduras ; dernière trace datée lue) ; en.wikipedia.org « Scandinavian Tobacco Group » (accord du 26 avril 2010 réunissant les activités cigares de Swedish Match, General Cigar comprise, et de Scandinavian Tobacco Group AB ; introduction en Bourse le 10 février 2016) ; en.wikipedia.org « General Cigar Company » (Swedish Match en 2005, STG en 2010, cession des parts de Swedish Match en 2016 selon cette page) ; cigar-coop.com « Cigar News: Swedish Match Sells Its Remaining Shares in Scandinavian Tobacco Group » (10 novembre 2017 : Swedish Match, 64 % de General Cigar en 2000, sort du capital de STG en 2017)')),
  `updated_at` = NOW()
 WHERE `name` = 'General Cigar';

-- ── Miami Cigar & Co. ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('et la distribue toujours ; León Jimenes aussi.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'et la distribue toujours ; León Jimenes aussi.', 'jusqu''en mars 2023 : en novembre 2022, La Aurora a annoncé qu''elle reprendrait elle-même sa distribution américaine, par une filiale, La Aurora USA, à compter du 1er avril 2023, et Miami Cigar n''en est plus le distributeur.'), `history`),
  `history_en` = IF(LOCATE(CAST('and still does; León Jimenes too.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'and still does; León Jimenes too.', 'until March 2023: in November 2022, La Aurora announced that it would take over its US distribution itself, through a subsidiary, La Aurora USA, from 1 April 2023, and Miami Cigar is no longer its distributor.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('y la sigue distribuyendo; León Jimenes también.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'y la sigue distribuyendo; León Jimenes también.', 'hasta marzo de 2023: en noviembre de 2022, La Aurora anunció que retomaría ella misma su distribución en Estados Unidos, mediante una filial, La Aurora USA, a partir del 1 de abril de 2023, y Miami Cigar ya no es su distribuidor.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('und tut es noch; León Jimenes ebenfalls.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'und tut es noch; León Jimenes ebenfalls.', 'bis März 2023: Im November 2022 kündigte La Aurora an, ihren Vertrieb in den Vereinigten Staaten ab dem 1. April 2023 selbst zu übernehmen, über eine Tochtergesellschaft, La Aurora USA, und Miami Cigar ist nicht mehr ihr Distributor.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('至今如此；León Jimenes 亦然。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '至今如此；León Jimenes 亦然。', '直到2023年3月：2022年11月，La Aurora 宣布将于2023年4月1日起，通过子公司 La Aurora USA 自行接管其在美国的分销；Miami Cigar 现已不再是其分销商。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وما زالت؛ وLeón Jimenes أيضًا.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وما زالت؛ وLeón Jimenes أيضًا.', 'حتى آذار/مارس 2023: ففي تشرين الثاني/نوفمبر 2022 أعلنت La Aurora أنها ستتولّى بنفسها توزيعها في الولايات المتحدة عبر شركة تابعة، La Aurora USA، اعتبارًا من 1 نيسان/أبريل 2023، ولم تعد Miami Cigar موزّعها.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Miami Cigar & Co.';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('La maison distribue aujourd''hui plus de vingt millions de cigares par an pour une série de fabricants' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'La maison distribue aujourd''hui plus de vingt millions de cigares par an pour une série de fabricants', 'La maison a dit distribuer plus de vingt millions de cigares par an pour une série de fabricants'), `history`),
  `history_en` = IF(LOCATE(CAST('The house today distributes more than twenty million cigars a year for a range of makers' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'The house today distributes more than twenty million cigars a year for a range of makers', 'The house has said it distributes more than twenty million cigars a year for a range of makers'), `history_en`),
  `history_es` = IF(LOCATE(CAST('La casa distribuye hoy más de veinte millones de puros al año para una serie de fabricantes' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'La casa distribuye hoy más de veinte millones de puros al año para una serie de fabricantes', 'La casa ha dicho distribuir más de veinte millones de puros al año para una serie de fabricantes'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Das Haus vertreibt heute über zwanzig Millionen Zigarren im Jahr für eine Reihe von Herstellern' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Das Haus vertreibt heute über zwanzig Millionen Zigarren im Jahr für eine Reihe von Herstellern', 'Das Haus hat erklärt, über zwanzig Millionen Zigarren im Jahr für eine Reihe von Herstellern zu vertreiben'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('公司如今每年为一系列制造商分销两千万余支雪茄' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '公司如今每年为一系列制造商分销两千万余支雪茄', '公司曾表示，每年为一系列制造商分销两千万余支雪茄'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وتوزّع الدار اليوم أكثر من عشرين مليون سيجار في السنة لمجموعة من الصانعين' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وتوزّع الدار اليوم أكثر من عشرين مليون سيجار في السنة لمجموعة من الصانعين', 'وقالت الدار إنها توزّع أكثر من عشرين مليون سيجار في السنة لمجموعة من الصانعين'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Miami Cigar & Co.';

UPDATE `brands` SET
  `factory` = 'Sans usine — Nestor Miranda : My Father (Estelí), Lancero 2026 : La Aurora ; Don Lino Africa : A.J. Fernandez (Estelí) ; Don Lino dominicaine : non communiquée ou El Artista ; Outcast : non nommée',
  `gamme` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"La ligne au nom du fondateur, lancée en 2014 et faite chez My Father à Estelí, dit Cigar Coop — la raison du classement de cette fiche. Le Grand Reserve 2024 de la marque y est roulé aussi (My Father Cigars S.A., juin 2025) ; le Private Reserve Lancero, annoncé en mars 2026, l''est à La Aurora, en République dominicaine.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"La marque des débuts, 1989, du prénom d''un homme de la fabrique d''UST au Honduras. Douze millions de cigares en 1996, deux ans hors marché, reprise chez La Aurora en 1999. Depuis 2021, la marque compte aussi une série dominicaine, Connecticut et Maduro : Cigar Coop écrit la fabrique non communiquée en juillet 2021, puis nomme Tabacalera El Artista en août 2021.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"La déclinaison plus sombre de la marque des débuts, relancée en 2019 : A.J. Fernandez la roule à Estelí, sous une cape Habano 2000 d''Équateur et un liant du Cameroun, disent Cigar Dojo et Cigar Coop en mai 2019 ; Cigar Coop la compte encore en août 2021 parmi les lignes d''A.J. Fernandez.","vitolas":[],"wrapper":"Habano 2000 d''Équateur"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","story":"Ligne présentée au salon PCA 2025 et expédiée aux détaillants en juin 2025, faite en République dominicaine ; en octobre 2026, la maison ne nomme pas la fabrique. Cape brésilienne Cubra, hybride de Corojo de graine cubaine, liant Sumatra d''Équateur et tripe dominicaine, en Robusto, Corona Gorda, Toro et Gran Toro selon l''annonce d''avril 2025.","vitolas":[],"wrapper":"Cubra du Brésil"}]',
  `gamme_en` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"The line in the founder''s name, launched in 2014 and made at My Father in Estelí, says Cigar Coop — the reason for this entry''s classification. The brand''s 2024 Grand Reserve is rolled there too (My Father Cigars S.A., June 2025); the Private Reserve Lancero, announced in March 2026, is rolled at La Aurora, in the Dominican Republic.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"The founding brand, 1989, after a man at UST''s Honduran factory. Twelve million cigars in 1996, two years off the market, resumed at La Aurora in 1999. Since 2021 the brand has also included a Dominican series, Connecticut and Maduro: Cigar Coop writes the factory as undisclosed in July 2021, then names Tabacalera El Artista in August 2021.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"The darker variation of the founding brand, relaunched in 2019: A.J. Fernandez rolls it in Estelí, under an Ecuadorian Habano 2000 wrapper and a binder from Cameroon, say Cigar Dojo and Cigar Coop in May 2019; Cigar Coop still counts it in August 2021 among A.J. Fernandez''s lines.","vitolas":[],"wrapper":"Ecuadorian Habano 2000"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","story":"Line presented at the PCA 2025 trade show and shipped to retailers in June 2025, made in the Dominican Republic; in October 2026, the company does not name the factory. Brazilian Cubra wrapper, a hybrid of Cuban-seed Corojo, Ecuadorian Sumatra binder and Dominican filler, in Robusto, Corona Gorda, Toro and Gran Toro according to the April 2025 announcement.","vitolas":[],"wrapper":"Brazilian Cubra"}]',
  `gamme_es` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"La línea con el nombre del fundador, lanzada en 2014 y hecha en My Father en Estelí, dice Cigar Coop — la razón de la clasificación de esta ficha. El Grand Reserve 2024 de la marca se lía allí también (My Father Cigars S.A., junio de 2025); el Private Reserve Lancero, anunciado en marzo de 2026, se lía en La Aurora, en la República Dominicana.","vitolas":[],"wrapper":"No divulgada"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"La marca de los inicios, 1989, por el nombre de un hombre de la fábrica de UST en Honduras. Doce millones de puros en 1996, dos años fuera del mercado, retomada en La Aurora en 1999. Desde 2021, la marca cuenta también con una serie dominicana, Connecticut y Maduro: Cigar Coop escribe la fábrica como no divulgada en julio de 2021, y luego nombra a Tabacalera El Artista en agosto de 2021.","vitolas":[],"wrapper":"No divulgada"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"La variante más oscura de la marca de los inicios, relanzada en 2019: A.J. Fernandez la lía en Estelí, con una capa Habano 2000 de Ecuador y un capote de Camerún, dicen Cigar Dojo y Cigar Coop en mayo de 2019; Cigar Coop la cuenta todavía en agosto de 2021 entre las líneas de A.J. Fernandez.","vitolas":[],"wrapper":"Habano 2000 de Ecuador"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","story":"Línea presentada en la feria PCA 2025 y enviada a los minoristas en junio de 2025, fabricada en República Dominicana; en octubre de 2026, la casa no nombra la fábrica. Capa brasileña Cubra, híbrido de Corojo de semilla cubana, capote Sumatra de Ecuador y tripa dominicana, en Robusto, Corona Gorda, Toro y Gran Toro según el anuncio de abril de 2025.","vitolas":[],"wrapper":"Cubra de Brasil"}]',
  `gamme_de` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"Die Linie mit dem Namen des Gründers, 2014 herausgebracht und bei My Father in Estelí gefertigt, sagt Cigar Coop — der Grund für die Einordnung dieses Eintrags. Die Grand Reserve 2024 der Marke wird dort ebenfalls gerollt (My Father Cigars S.A., Juni 2025); die Private Reserve Lancero, im März 2026 angekündigt, wird bei La Aurora in der Dominikanischen Republik gerollt.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"Die Marke der Anfänge, 1989, nach einem Mann in der UST-Fabrik in Honduras. Zwölf Millionen Zigarren 1996, zwei Jahre vom Markt, 1999 bei La Aurora wieder aufgenommen. Seit 2021 umfasst die Marke auch eine dominikanische Serie, Connecticut und Maduro: Cigar Coop gibt die Fabrik im Juli 2021 als nicht angegeben an und nennt im August 2021 dann Tabacalera El Artista.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"Die dunklere Variante der Gründungsmarke, 2019 neu aufgelegt: A.J. Fernandez rollt sie in Estelí, unter einem Deckblatt Habano 2000 aus Ecuador und einem Umblatt aus Kamerun, sagen Cigar Dojo und Cigar Coop im Mai 2019; Cigar Coop zählt sie im August 2021 noch immer zu den Linien von A.J. Fernandez.","vitolas":[],"wrapper":"Habano 2000 aus Ecuador"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","story":"Linie, die auf der Messe PCA 2025 vorgestellt und im Juni 2025 an den Einzelhandel versandt wurde, hergestellt in der Dominikanischen Republik; im Oktober 2026 nennt das Haus die Fabrik nicht. Brasilianisches Deckblatt Cubra, ein Hybrid des Corojo aus kubanischer Saat, Sumatra-Umblatt aus Ecuador und dominikanische Einlage, in Robusto, Corona Gorda, Toro und Gran Toro laut der Ankündigung vom April 2025.","vitolas":[],"wrapper":"Cubra aus Brasilien"}]',
  `gamme_zh` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"以创始人命名的系列，据 Cigar Coop 所述，2014年推出，在埃斯特利的 My Father 制作——本词条归类的依据。该品牌的 Grand Reserve 2024 也在那里卷制（My Father Cigars S.A.，2025年6月）；2026年3月宣布的 Private Reserve Lancero 则在多米尼加共和国的 La Aurora 卷制。","vitolas":[],"wrapper":"未公开"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"1989年起家的牌子，取自 UST 洪都拉斯工厂里一个人的名字。1996年一千两百万支，离市两年，1999年在 La Aurora 恢复生产。2021年起，该牌子还有一个多米尼加系列，Connecticut 与 Maduro：Cigar Coop 在2021年7月把工厂写作未公开，2021年8月则点名 Tabacalera El Artista。","vitolas":[],"wrapper":"未公开"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"起家牌子的深色变体，2019年重新推出：A.J. Fernandez 在埃斯特利卷制，茄衣为厄瓜多尔的 Habano 2000，茄套产自喀麦隆，据 Cigar Dojo 与 Cigar Coop 2019年5月所述；Cigar Coop 在2021年8月仍把它列在 A.J. Fernandez 的系列之中。","vitolas":[],"wrapper":"厄瓜多尔 Habano 2000"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","story":"该产品线在PCA 2025展会上亮相，2025年六月发运给零售商，在多米尼加共和国制造；2026年十月，该公司未点明工厂。茄衣为巴西Cubra，是古巴种子Corojo的杂交品种，茄套为厄瓜多尔Sumatra，茄芯为多米尼加所产，规格为Robusto、Corona Gorda、Toro和Gran Toro，据2025年四月的公告。","vitolas":[],"wrapper":"巴西Cubra"}]',
  `gamme_ar` = '[{"name":"Nestor Miranda Collection","color":"#6B4226","force":"Medium-Full","story":"الخطّ الذي يحمل اسم المؤسّس، أُطلق عام 2014 ويُصنع لدى My Father في إستيلي، بحسب Cigar Coop — سبب تصنيف هذه البطاقة. ويُلفّ هناك أيضًا Grand Reserve 2024 للعلامة (My Father Cigars S.A.، حزيران/يونيو 2025)؛ أمّا Private Reserve Lancero، المعلَن عنه في آذار/مارس 2026، فيُلفّ لدى La Aurora في الجمهورية الدومينيكية.","vitolas":[],"wrapper":"غير معلن"},{"name":"Don Lino","color":"#8B5A2B","force":"Medium","story":"علامة البدايات، 1989، على اسم رجل في مصنع UST بهندوراس. اثنا عشر مليون سيجار سنة 1996، وسنتان خارج السوق، واستُؤنف صنعها لدى La Aurora سنة 1999. ومنذ 2021 تضمّ العلامة أيضًا سلسلة دومينيكية، Connecticut وMaduro: تكتب Cigar Coop أنّ المصنع غير معلن في تموز/يوليو 2021، ثم تسمّي Tabacalera El Artista في آب/أغسطس 2021.","vitolas":[],"wrapper":"غير معلن"},{"name":"Don Lino Africa","color":"#4A3728","force":"Full","story":"التنويع الأدكن لعلامة البدايات، أُعيد إطلاقه سنة 2019: يلفّه A.J. Fernandez في إستيلي، بغلاف Habano 2000 من الإكوادور ورباط من الكاميرون، بحسب Cigar Dojo وCigar Coop في أيار/مايو 2019؛ ولا تزال Cigar Coop تعدّه في آب/أغسطس 2021 بين خطوط A.J. Fernandez.","vitolas":[],"wrapper":"Habano 2000 من الإكوادور"},{"name":"Outcast","color":"#8B5A2B","force":"Mild-Medium","story":"خط قُدّم في معرض PCA 2025 وشُحن إلى تجار التجزئة في يونيو 2025، صُنع في جمهورية الدومينيكان؛ وفي أكتوبر 2026 لا تسمّي الشركة المصنع. غلاف خارجي Cubra برازيلي، هجين من Corojo من بذور كوبية، ورابط Sumatra من الإكوادور، وحشوة دومينيكانية، بمقاسات Robusto وCorona Gorda وToro وGran Toro بحسب إعلان أبريل 2025.","vitolas":[],"wrapper":"Cubra من البرازيل"}]',
  `source` = IF(LOCATE(CAST('cigar-coop.com « Cigar News: La Aurora Establishes U.S.-Base' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « Cigar News: La Aurora Establishes U.S.-Based Company and Will Assume Control of its Sales and Marketing in April 2023 » (11 novembre 2022 : La Aurora USA reprend de Miami Cigar and Company toute la vente et le marketing au 1er avril 2023 ; commandes via Miami Cigar jusqu''au 31 mars 2023) ; cigaraficionado.com « La Aurora Brings Distribution In House » (14 novembre 2022 : après plus de trente ans de distribution par Miami Cigar & Co., La Aurora vend elle-même à partir du 1er avril) ; cigardojo.com « La Aurora Now Has In-House Distribution in USA » (3 avril 2023 : distribution interne lancée, fin de l''accord avec Miami Cigar & Co.) ; cigaraficionado.com « La Aurora Turns to Arango for Midwest Distribution » (1er août 2023 : Arango pour six États du Midwest, La Aurora USA pour le reste) ; cigardojo.com « La Aurora to Adjust Prices Amid Rising Costs » (24 avril 2025 : Ed McKenna, directeur général de La Aurora USA, cité) ; cigar-coop.com « Cigar News: Miami Cigar Company Launching Don Lino Dominican » (6 juillet 2021 : Don Lino Connecticut et Maduro, fabrique non communiquée) ; cigar-coop.com « PCA 2021 Report: Miami Cigar & Company » (4 août 2021 : Don Lino Africa chez A.J. Fernandez, Don Lino Dominican chez Tabacalera El Artista) ; cigar-coop.com « Cigar News: Miami Cigar Company to Bring Back Don Lino Africa » (28 mai 2019 : production par Tabacalera A.J. Fernandez) ; cigardojo.com « Miami Cigar Don Lino Africa » (28 mai 2019 : usine A.J. Fernández d''Estelí, cape Habano 2000 d''Équateur, liant du Cameroun) ; cigar-coop.com « Cigar News: Nestor Miranda Collection » (4 juin 2014 : Connecticut, Habano et Maduro produits chez My Father, à Estelí) ; cigar-coop.com « Nestor Miranda Grand Reserve 2024 Cigar Review » (19 juin 2025 : My Father Cigars S.A., Nicaragua) ; cigardojo.com « Miami Cigar Co. Brings Back Private Reserve Lancero » (30 mars 2026 : Nestor Miranda Private Reserve Lancero produit à La Aurora, République dominicaine) ; cigar-coop.com « Tatiana Cappuccino and Amaretto Classic and Tin Offerings Shipped » (24 août 2026 : nouveaux formats Tatiana expédiés par Miami Cigar and Company ; aucune fabrique citée) ; miamicigar.com (octobre 2026 : Tatiana, Nestor Miranda, Outcast et Don Lino ; La Aurora n''y figure pas)')),
  `updated_at` = NOW()
 WHERE `name` = 'Miami Cigar & Co.';

-- ── Ozgener Family Cigars ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Elle n''a pas d''usine. Bosphorus et Pi sont roulés chez Luciano, à Estelí — la fabrique d''Eradio Pichardo dont l''atlas porte la fiche ; Aramas, la ligne régulière de mars 2024, nommée d''après le mont Ararat, l''est à La Alianza, la fabrique d''E.P. Carrillo en République dominicaine. La fiche est classée là où sort la majorité, au Nicaragua, et nomme les deux.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Elle n''a pas d''usine. Bosphorus et Pi sont roulés chez Luciano, à Estelí — la fabrique d''Eradio Pichardo dont l''atlas porte la fiche ; Aramas, la ligne régulière de mars 2024, nommée d''après le mont Ararat, l''est à La Alianza, la fabrique d''E.P. Carrillo en République dominicaine. La fiche est classée là où sort la majorité, au Nicaragua, et nomme les deux.', 'Elle n''a pas d''usine. Bosphorus, annoncé en juin 2022, a d''abord été roulé à Estelí chez Luciano, ex-Tabacalera Pichardo — la fabrique d''Eradio Pichardo dont l''atlas porte la fiche —, puis confié en novembre 2022 à Tabacalera La Alianza, la fabrique d''E.P. Carrillo en République dominicaine, rebaptisée Casa Carrillo en 2024, où sont aussi roulées Aramas, deuxième ligne, annoncée en mars 2023 et nommée d''après le mont Ararat, et Firsat, en 2024. Karatoba (2025) vient de NACSA, à Estelí ; Maracana (mars 2026), de My Father au Honduras ; l''édition limitée World Cup 2026, de My Father au Nicaragua. La fiche reste classée au Nicaragua, mais trois des cinq lignes courantes sortent de République dominicaine.'), `history`),
  `history_en` = IF(LOCATE(CAST('Bosphorus and Pi are rolled at Luciano, in Estelí — Eradio Pichardo''s factory, whose entry this atlas carries; Aramas, the regular line of March 2024, named after Mount Ararat, is rolled at La Alianza, E.P. Carrillo''s factory in the Dominican Republic. The entry is classified where the majority comes out, in Nicaragua, and names both.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Bosphorus and Pi are rolled at Luciano, in Estelí — Eradio Pichardo''s factory, whose entry this atlas carries; Aramas, the regular line of March 2024, named after Mount Ararat, is rolled at La Alianza, E.P. Carrillo''s factory in the Dominican Republic. The entry is classified where the majority comes out, in Nicaragua, and names both.', 'Bosphorus, announced in June 2022, was first rolled in Estelí at Luciano, formerly Tabacalera Pichardo (Eradio Pichardo''s factory, whose entry this atlas carries), then entrusted in November 2022 to Tabacalera La Alianza, E.P. Carrillo''s factory in the Dominican Republic, renamed Casa Carrillo in 2024, where Aramas, the second line, announced in March 2023 and named after Mount Ararat, and Firsat, in 2024, are also rolled. Karatoba (2025) comes from NACSA, in Estelí; Maracana (March 2026), from My Father in Honduras; the limited edition World Cup 2026, from My Father in Nicaragua. The entry remains classified in Nicaragua, but three of the five current lines come out of the Dominican Republic.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Bosphorus y Pi se lían en Luciano, en Estelí — la fábrica de Eradio Pichardo cuya ficha lleva este atlas; Aramas, la línea regular de marzo de 2024, nombrada por el monte Ararat, se lía en La Alianza, la fábrica de E.P. Carrillo en la República Dominicana. La ficha se clasifica donde sale la mayoría, en Nicaragua, y nombra a ambas.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Bosphorus y Pi se lían en Luciano, en Estelí — la fábrica de Eradio Pichardo cuya ficha lleva este atlas; Aramas, la línea regular de marzo de 2024, nombrada por el monte Ararat, se lía en La Alianza, la fábrica de E.P. Carrillo en la República Dominicana. La ficha se clasifica donde sale la mayoría, en Nicaragua, y nombra a ambas.', 'Bosphorus, anunciado en junio de 2022, fue liado primero en Estelí, en Luciano, antes Tabacalera Pichardo — la fábrica de Eradio Pichardo cuya ficha lleva este atlas —, y confiado después, en noviembre de 2022, a Tabacalera La Alianza, la fábrica de E.P. Carrillo en la República Dominicana, rebautizada Casa Carrillo en 2024, donde se lían también Aramas, segunda línea, anunciada en marzo de 2023 y nombrada por el monte Ararat, y Firsat, en 2024. Karatoba (2025) viene de NACSA, en Estelí; Maracana (marzo de 2026), de My Father en Honduras; la edición limitada World Cup 2026, de My Father en Nicaragua. La ficha sigue clasificada en Nicaragua, pero tres de las cinco líneas actuales salen de la República Dominicana.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Bosphorus und Pi werden bei Luciano in Estelí gerollt — der Fabrik von Eradio Pichardo, deren Eintrag dieser Atlas führt; Aramas, die reguläre Linie vom März 2024, nach dem Berg Ararat benannt, bei La Alianza, der Fabrik von E.P. Carrillo in der Dominikanischen Republik. Der Eintrag ist dort eingeordnet, wo die Mehrheit herauskommt, in Nicaragua, und nennt beide.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Bosphorus und Pi werden bei Luciano in Estelí gerollt — der Fabrik von Eradio Pichardo, deren Eintrag dieser Atlas führt; Aramas, die reguläre Linie vom März 2024, nach dem Berg Ararat benannt, bei La Alianza, der Fabrik von E.P. Carrillo in der Dominikanischen Republik. Der Eintrag ist dort eingeordnet, wo die Mehrheit herauskommt, in Nicaragua, und nennt beide.', 'Bosphorus, im Juni 2022 angekündigt, wurde zuerst in Estelí bei Luciano gerollt, früher Tabacalera Pichardo — der Fabrik von Eradio Pichardo, deren Eintrag dieser Atlas führt —, dann im November 2022 Tabacalera La Alianza anvertraut, der Fabrik von E.P. Carrillo in der Dominikanischen Republik, 2024 in Casa Carrillo umbenannt, wo auch Aramas, die zweite Linie (im März 2023 angekündigt, nach dem Berg Ararat benannt), und Firsat (2024) gerollt werden. Karatoba (2025) kommt von NACSA in Estelí; Maracana (März 2026) von My Father in Honduras; die limitierte Edition World Cup 2026 von My Father in Nicaragua. Der Eintrag bleibt in Nicaragua eingeordnet, aber drei der fünf laufenden Linien kommen aus der Dominikanischen Republik.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Bosphorus 与 Pi 在埃斯特利的 Luciano 卷制——埃拉迪奥·皮查尔多的工厂，本图集载有其词条；2024年3月的常规系列 Aramas，以阿拉拉特山命名，在多米尼加共和国 E.P. Carrillo 的 La Alianza 工厂卷制。词条按多数产量所在地归入尼加拉瓜，并点出两厂。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Bosphorus 与 Pi 在埃斯特利的 Luciano 卷制——埃拉迪奥·皮查尔多的工厂，本图集载有其词条；2024年3月的常规系列 Aramas，以阿拉拉特山命名，在多米尼加共和国 E.P. Carrillo 的 La Alianza 工厂卷制。词条按多数产量所在地归入尼加拉瓜，并点出两厂。', 'Bosphorus 于2022年6月宣布，最初在埃斯特利的 Luciano（前称 Tabacalera Pichardo）卷制——那是埃拉迪奥·皮查尔多的工厂，本图集载有其词条——2022年11月起改交多米尼加共和国 E.P. Carrillo 的工厂 Tabacalera La Alianza（2024年更名为 Casa Carrillo）卷制；该厂也卷制第二条线 Aramas（2023年3月宣布，以阿拉拉特山命名）与2024年的 Firsat。Karatoba（2025年）来自埃斯特利的 NACSA；Maracana（2026年3月）来自洪都拉斯的 My Father；限量版 World Cup 2026 来自尼加拉瓜的 My Father。词条仍归入尼加拉瓜，但五个现行系列中有三个出自多米尼加共和国。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('يُلفّ Bosphorus وPi لدى Luciano في إستيلي — مصنع إراديو بيتشاردو الذي يحمل هذا الأطلس بطاقته؛ أمّا Aramas، الخطّ المنتظم من آذار/مارس 2024، المسمّى على جبل أرارات، فيُلفّ في La Alianza، مصنع E.P. Carrillo في جمهورية الدومينيكان. تُصنَّف البطاقة حيث تخرج الأغلبية، في نيكاراغوا، وتسمّي الاثنين.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'يُلفّ Bosphorus وPi لدى Luciano في إستيلي — مصنع إراديو بيتشاردو الذي يحمل هذا الأطلس بطاقته؛ أمّا Aramas، الخطّ المنتظم من آذار/مارس 2024، المسمّى على جبل أرارات، فيُلفّ في La Alianza، مصنع E.P. Carrillo في جمهورية الدومينيكان. تُصنَّف البطاقة حيث تخرج الأغلبية، في نيكاراغوا، وتسمّي الاثنين.', 'أُعلن عن Bosphorus في حزيران/يونيو 2022، ولُفّ أولًا في إستيلي لدى Luciano، المعروف سابقًا باسم Tabacalera Pichardo — وهو مصنع إراديو بيتشاردو الذي يحمل هذا الأطلس بطاقته —، ثم أُوكل في تشرين الثاني/نوفمبر 2022 إلى Tabacalera La Alianza، مصنع E.P. Carrillo في جمهورية الدومينيكان، الذي أُعيدت تسميته Casa Carrillo في 2024، وفيه يُلفّ أيضًا Aramas، الخطّ الثاني، المعلن عنه في آذار/مارس 2023 والمسمّى على جبل أرارات، وFirsat في 2024. ويأتي Karatoba (2025) من NACSA في إستيلي؛ وMaracana (آذار/مارس 2026) من My Father في هندوراس؛ والإصدار المحدود World Cup 2026 من My Father في نيكاراغوا. وتبقى البطاقة مصنّفة في نيكاراغوا، لكنّ ثلاثة من الخطوط الخمسة الجارية تخرج من جمهورية الدومينيكان.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Ozgener Family Cigars';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Crowned Heads, dont Tim Ozgener est devenu investisseur en 2022, les distribue' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Crowned Heads, dont Tim Ozgener est devenu investisseur en 2022, les distribue', 'Crowned Heads, dont Tim Ozgener est devenu investisseur en 2022 puis directeur général en avril 2025, les distribue'), `history`),
  `history_en` = IF(LOCATE(CAST('Crowned Heads, in which Tim Ozgener became an investor in 2022, distributes them' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Crowned Heads, in which Tim Ozgener became an investor in 2022, distributes them', 'Crowned Heads, in which Tim Ozgener became an investor in 2022 and then chief executive in April 2025, distributes them'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Crowned Heads, en la que Tim Ozgener se convirtió en inversor en 2022, los distribuye' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Crowned Heads, en la que Tim Ozgener se convirtió en inversor en 2022, los distribuye', 'Crowned Heads, en la que Tim Ozgener se convirtió en inversor en 2022 y después en director general en abril de 2025, los distribuye'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Crowned Heads, deren Investor Tim Ozgener 2022 geworden ist, vertreibt sie' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Crowned Heads, deren Investor Tim Ozgener 2022 geworden ist, vertreibt sie', 'Crowned Heads, deren Investor Tim Ozgener 2022 und deren Geschäftsführer er im April 2025 geworden ist, vertreibt sie'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('（Tim Ozgener于2022年成为其投资人）' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '（Tim Ozgener于2022年成为其投资人）', '（Tim Ozgener于2022年成为其投资人，并于2025年四月出任总经理）'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('التي أصبح Tim Ozgener مستثمرًا فيها في 2022' AS BINARY), CAST(`history_ar` AS BINARY)) > 0 AND LOCATE(CAST('التي أصبح Tim Ozgener مستثمرًا فيها في 2022 ثم مديرًا عامًّا لها في أبريل 2025' AS BINARY), CAST(`history_ar` AS BINARY)) = 0, REPLACE(`history_ar`, 'التي أصبح Tim Ozgener مستثمرًا فيها في 2022', 'التي أصبح Tim Ozgener مستثمرًا فيها في 2022 ثم مديرًا عامًّا لها في أبريل 2025'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Ozgener Family Cigars';

UPDATE `brands` SET
  `founded` = '2022 — Tim Ozgener',
  `factory` = 'Sans usine — Casa Carrillo (ex-La Alianza, Rép. dominicaine) : Bosphorus, Aramas, Firsat ; NACSA, Estelí : Karatoba ; My Father : Maracana (Honduras), World Cup 2026 (Nicaragua)',
  `gamme` = '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","story":"Le détroit d''Istanbul — la première ligne, annoncée en juin 2022 : roulée d''abord chez Tabacalera Pichardo, à Estelí, puis, depuis novembre 2022, à Tabacalera La Alianza (devenue Casa Carrillo), en République dominicaine, dit la maison. Cape Habano 2000 d''Équateur, double liant d''Équateur et du Nicaragua, tripe d''Estelí, de Jalapa et d''Ometepe ; formats pressés en boîte.","vitolas":[],"wrapper":"Habano 2000 d''Équateur"},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","story":"La couleur et la perception, en édition limitée. La version Yellow de 2022 a été roulée chez Tabacalera Pichardo, à Estelí ; la Red, en 2023, passe à Tabacalera La Alianza, en République dominicaine, dit Cigar Coop ; Cigars Direct la propose encore en octobre 2026.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","story":"Le mont Ararat. La deuxième ligne de la maison, annoncée en mars 2023, roulée à La Alianza, chez E.P. Carrillo, devenue Casa Carrillo en 2024, en République dominicaine. Cape San Andrés du Mexique, liant Sumatra d''Équateur, tripe de République dominicaine, du Nicaragua et de Connecticut Broadleaf américain, dit Cigar Coop en juillet 2024.","vitolas":[],"wrapper":"San Andrés du Mexique"}]',
  `gamme_en` = '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","story":"The Istanbul strait — the first line, announced in June 2022: rolled first at Tabacalera Pichardo, in Estelí, then, since November 2022, at Tabacalera La Alianza (which became Casa Carrillo), in the Dominican Republic, says the house. Ecuadorian Habano 2000 wrapper, double binder from Ecuador and Nicaragua, filler from Estelí, Jalapa and Ometepe; box-pressed formats.","vitolas":[],"wrapper":"Ecuadorian Habano 2000"},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","story":"Colour and perception, in limited edition. The Yellow version of 2022 was rolled at Tabacalera Pichardo, in Estelí; the Red, in 2023, moves to Tabacalera La Alianza, in the Dominican Republic, says Cigar Coop; Cigars Direct still offers it in October 2026.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","story":"Mount Ararat. The house''s second line, announced in March 2023, rolled at La Alianza, at E.P. Carrillo, which became Casa Carrillo in 2024, in the Dominican Republic. Mexican San Andrés wrapper, Ecuadorian Sumatra binder, filler from the Dominican Republic, Nicaragua and American Connecticut Broadleaf, says Cigar Coop in July 2024.","vitolas":[],"wrapper":"Mexican San Andrés"}]',
  `gamme_es` = '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","story":"El estrecho de Estambul — la primera línea, anunciada en junio de 2022: liada primero en Tabacalera Pichardo, en Estelí, y después, desde noviembre de 2022, en Tabacalera La Alianza (convertida en Casa Carrillo), en la República Dominicana, dice la casa. Capa Habano 2000 de Ecuador, doble capote de Ecuador y Nicaragua, tripa de Estelí, Jalapa y Ometepe; formatos prensados en caja.","vitolas":[],"wrapper":"Habano 2000 de Ecuador"},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","story":"El color y la percepción, en edición limitada. La versión Yellow de 2022 se lió en Tabacalera Pichardo, en Estelí; la Red, en 2023, pasa a Tabacalera La Alianza, en la República Dominicana, dice Cigar Coop; Cigars Direct la ofrece todavía en octubre de 2026.","vitolas":[],"wrapper":"No divulgada"},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","story":"El monte Ararat. La segunda línea de la casa, anunciada en marzo de 2023, liada en La Alianza, en E.P. Carrillo, convertida en Casa Carrillo en 2024, en la República Dominicana. Capa San Andrés de México, capote Sumatra de Ecuador, tripa de República Dominicana, de Nicaragua y de Connecticut Broadleaf estadounidense, dice Cigar Coop en julio de 2024.","vitolas":[],"wrapper":"San Andrés de México"}]',
  `gamme_de` = '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","story":"Die Meerenge von Istanbul — die erste Linie, im Juni 2022 angekündigt: zuerst bei Tabacalera Pichardo in Estelí gerollt, dann, seit November 2022, bei Tabacalera La Alianza (zu Casa Carrillo geworden) in der Dominikanischen Republik, so das Haus. Habano-2000-Deckblatt aus Ecuador, doppeltes Umblatt aus Ecuador und Nicaragua, Einlage aus Estelí, Jalapa und Ometepe; Formate in Schachtelpressung.","vitolas":[],"wrapper":"Habano 2000 aus Ecuador"},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","story":"Farbe und Wahrnehmung, in limitierter Auflage. Die Version Yellow von 2022 wurde bei Tabacalera Pichardo in Estelí gerollt; die Red wechselt 2023 zu Tabacalera La Alianza in der Dominikanischen Republik, so Cigar Coop; Cigars Direct bietet sie im Oktober 2026 weiterhin an.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","story":"Der Berg Ararat. Die zweite Linie des Hauses, im März 2023 angekündigt, bei La Alianza, E.P. Carrillo, gerollt, 2024 zu Casa Carrillo geworden, in der Dominikanischen Republik. San-Andrés-Deckblatt aus Mexiko, Sumatra-Umblatt aus Ecuador, Einlage aus der Dominikanischen Republik, aus Nicaragua und aus amerikanischem Connecticut Broadleaf, so Cigar Coop im Juli 2024.","vitolas":[],"wrapper":"San Andrés aus Mexiko"}]',
  `gamme_zh` = '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","story":"伊斯坦布尔海峡——首个系列，2022年6月宣布：最初在埃斯特利的 Tabacalera Pichardo 卷制，2022年11月起改在多米尼加共和国的 Tabacalera La Alianza（后更名 Casa Carrillo）卷制，据该公司称。茄衣为厄瓜多尔 Habano 2000，双层茄套来自厄瓜多尔和尼加拉瓜，茄芯来自埃斯特利、哈拉帕和奥梅特佩；盒压规格。","vitolas":[],"wrapper":"厄瓜多尔 Habano 2000"},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","story":"色彩与感知，限量版。2022年的 Yellow 版在埃斯特利的 Tabacalera Pichardo 卷制；2023年的 Red 版转至多米尼加共和国的 Tabacalera La Alianza，据 Cigar Coop 称；Cigars Direct 在2026年10月仍有销售。","vitolas":[],"wrapper":"未公开"},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","story":"阿拉拉特山。该公司的第二条线，2023年3月宣布，在多米尼加共和国 E.P. Carrillo 的 La Alianza 卷制，该厂2024年更名为 Casa Carrillo。茄衣为墨西哥 San Andrés，茄套为厄瓜多尔 Sumatra，茄芯来自多米尼加共和国、尼加拉瓜和美国 Connecticut Broadleaf，据 Cigar Coop 在2024年7月所述。","vitolas":[],"wrapper":"墨西哥 San Andrés"}]',
  `gamme_ar` = '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","story":"مضيق إسطنبول — الخطّ الأوّل، أُعلن عنه في حزيران/يونيو 2022: لُفّ أولًا لدى Tabacalera Pichardo في إستيلي، ثم، منذ تشرين الثاني/نوفمبر 2022، لدى Tabacalera La Alianza (التي صارت Casa Carrillo) في جمهورية الدومينيكان، تقول الدار. غلاف Habano 2000 من الإكوادور، ورباط مزدوج من الإكوادور ونيكاراغوا، وحشوة من إستيلي وخالابا وأوميتيبي؛ مقاسات مكبوسة في العلبة.","vitolas":[],"wrapper":"Habano 2000 من الإكوادور"},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","story":"اللون والإدراك، بإصدار محدود. نسخة Yellow من 2022 لُفّت لدى Tabacalera Pichardo في إستيلي؛ أمّا نسخة Red في 2023 فتنتقل إلى Tabacalera La Alianza في جمهورية الدومينيكان، بحسب Cigar Coop؛ ولا تزال Cigars Direct تعرضها في تشرين الأول/أكتوبر 2026.","vitolas":[],"wrapper":"غير معلن"},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","story":"جبل أرارات. الخطّ الثاني للدار، أُعلن عنه في آذار/مارس 2023، يُلفّ في La Alianza لدى E.P. Carrillo، التي صارت Casa Carrillo في 2024، في جمهورية الدومينيكان. غلاف San Andrés من المكسيك، ورباط Sumatra من الإكوادور، وحشوة من جمهورية الدومينيكان ونيكاراغوا ومن Connecticut Broadleaf الأمريكي، بحسب Cigar Coop في تموز/يوليو 2024.","vitolas":[],"wrapper":"San Andrés من المكسيك"}]',
  `source` = IF(LOCATE(CAST('cigar-coop.com « Cigar News: Ozgener Family Cigars Shifts Pr' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigar-coop.com « Cigar News: Ozgener Family Cigars Shifts Production of Bosphorus to Tabacalera La Alianza » (2 novembre 2022 : Bosphorus passe de Tabacalera Pichardo à Tabacalera La Alianza ; cape Sumatra remplacée par une cape Habano 2000 d''Équateur) ; cigaraficionado.com « Ernesto Perez-Carrillo Making Cigars for Tim Ozgener » (2 novembre 2022 : Bosphorus, d''abord à Tabacalera Pichardo, au Nicaragua, passe à Tabacalera La Alianza, en République dominicaine) ; cigar-coop.com « Cigar News: Tim Ozgener Returning to Cigar Industry » (29 juin 2022 : Bosphorus annoncée, produite par Tabacalera Pichardo) ; cigar-coop.com « Cigar News: Ozgener Family Cigars Announces Aramas Line » (23 mars 2023 : deuxième ligne, Tabacalera La Alianza, expédition en avril) ; cigar-coop.com « PCA 2023: Ozgener Family Cigars » (13 juillet 2023 : Bosphorus à La Alianza ; Pi Synesthesia Yellow de 2022 chez Pichardo, Red de 2023 chez La Alianza ; Aramas à La Alianza) ; blindmanspuff.com « Tabacalera La Alianza Renamed to Casa Carrillo » (3 mars 2024 : La Alianza rebaptisée Casa Carrillo, République dominicaine) ; cigar-coop.com « PCA 2024: Oz Family Cigars » (3 avril 2024 : Casa Carrillo fait toutes les offres actuelles de la maison) ; cigar-coop.com « Ozgener Family Cigars to Launch Firsat at PCA 2024 » (15 mars 2024 : Firsat, troisième ligne courante, Casa Carrillo, République dominicaine) ; cigaraficionado.com « Ozgener Family Cigars Ships Firsat » (2 juillet 2024 : Firsat faite à Casa Carrillo, République dominicaine) ; cigar-coop.com « Aramas A55 by Oz Family Cigars » (5 juillet 2024 : Casa Carrillo, République dominicaine) ; cigar-coop.com « Firsat F52 by Oz Family Cigars » (6 juillet 2025 : Casa Carrillo, République dominicaine) ; cigar-coop.com « Oz Family Cigars to Release Karatoba » (22 mars 2025 : NACSA, Nicaragua, première fois que la maison travaille avec cette fabrique) ; cigar-coop.com « Karatoba K50 Toro by Oz Family Cigars Cigar Review » (16 juin 2026 : NACSA, Estelí) ; cigar-coop.com « Oz Family Cigars to Release Maracana at PCA 2026 » (31 mars 2026 : My Father Cigars Honduras, Honduras ; cinquième ligne courante) ; cigaraficionado.com « Two Soccer-Themed Smokes From OZ Family Cigars » (20 mars 2026 : Maracana chez My Father Cigars Honduras, World Cup 2026 chez My Father Cigars S.A., Nicaragua ; distribution Crowned Heads) ; cigaraficionado.com « Conder Retiring From Crowned Heads » (4 avril 2025 : Tim Ozgener devient directeur général de Crowned Heads) ; ozfamilycigars.com « Bosphorus » (octobre 2026 : faite à Tabacalera La Alianza, Santiago, République dominicaine ; accueil : Karatoba, Aramas, Bosphorus, Firsat, Maracana, World Cup 2026) ; cigarsdirect.com « Buy OZ Family Cigars Online at Discount Prices & Save » (octobre 2026 : Maracana, Karatoba, Firsat, Aramas, World Cup 2026 et Pi Synesthesia Red en stock)')),
  `updated_at` = NOW()
 WHERE `name` = 'Ozgener Family Cigars';

