-- ── Tabacalera Palma ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('José Arnaldo Blanco II la fonde en 1936.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'José Arnaldo Blanco II la fonde en 1936.', 'José Arnaldo Blanco II l''établit en 1925 et en dépose l''enregistrement industriel en 1936, dit la maison sur sa page de présentation ; sa page d''accueil et Cigar Coop, qui note en mars 2026 ses quatre-vingt-dix ans, comptent l''activité depuis 1936, et un article de la Premium Cigar Association d''avril 2024 écrit les deux dates.'), `history`),
  `history_en` = IF(LOCATE(CAST('José Arnaldo Blanco II founded it in 1936.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'José Arnaldo Blanco II founded it in 1936.', 'José Arnaldo Blanco II established it in 1925 and filed its industrial registration in 1936, says the house on its presentation page; its home page and Cigar Coop, which notes its ninety years in March 2026, date its activity from 1936, and an article by the Premium Cigar Association of April 2024 writes both dates.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('José Arnaldo Blanco II la funda en 1936.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'José Arnaldo Blanco II la funda en 1936.', 'José Arnaldo Blanco II la establece en 1925 y presenta su registro industrial en 1936, dice la casa en su página de presentación; su página de inicio y Cigar Coop, que anota en marzo de 2026 sus noventa años, cuentan la actividad desde 1936, y un artículo de la Premium Cigar Association de abril de 2024 escribe las dos fechas.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('José Arnaldo Blanco II gründete sie 1936.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'José Arnaldo Blanco II gründete sie 1936.', 'José Arnaldo Blanco II baute sie 1925 auf und reichte 1936 ihre gewerbliche Eintragung ein, so das Haus auf seiner Vorstellungsseite; seine Startseite und Cigar Coop, das im März 2026 deren neunzig Jahre vermerkt, rechnen die Tätigkeit ab 1936, und ein Artikel der Premium Cigar Association vom April 2024 nennt beide Daten.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('José Arnaldo Blanco II 于 1936 年创办了它。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'José Arnaldo Blanco II 于 1936 年创办了它。', 'José Arnaldo Blanco II 于 1925年设立了它，并于 1936年提交工业登记，该公司在其介绍页面上如此说明；其首页与 Cigar Coop（后者在 2026年3月注明其已有九十年）都把业务从 1936年算起，Premium Cigar Association 2024年4月的一篇文章则写出了这两个年份。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أسّسه خوسيه أرنالدو بلانكو الثاني عام 1936.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أسّسه خوسيه أرنالدو بلانكو الثاني عام 1936.', 'أقامه خوسيه أرنالدو بلانكو الثاني عام 1925 وأودع تسجيله الصناعي عام 1936، بحسب الدار في صفحتها التعريفية؛ وصفحتها الرئيسية وCigar Coop، الذي يذكر في مارس 2026 أنّ عمره تسعون سنة، تحسبان النشاط منذ 1936، ويكتب مقال لـ Premium Cigar Association في أبريل 2024 التاريخين معًا.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera Palma';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('était un Espagnol arrivé en République dominicaine au milieu du XIXe siècle.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'était un Espagnol arrivé en République dominicaine au milieu du XIXe siècle.', 'était un Espagnol arrivé en République dominicaine — au milieu du XIXe siècle, selon la maison, qui y place les origines de l''entreprise ; à la fin des années 1880, selon un article de la Premium Cigar Association d''avril 2024.'), `history`),
  `history_en` = IF(LOCATE(CAST('was a Spaniard who reached the Dominican Republic in the middle of the nineteenth century.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'was a Spaniard who reached the Dominican Republic in the middle of the nineteenth century.', 'was a Spaniard who reached the Dominican Republic — in the middle of the nineteenth century, according to the house, which places the origins of the company there; in the late 1880s, according to an article by the Premium Cigar Association of April 2024.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('era un español llegado a la República Dominicana a mediados del siglo XIX.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'era un español llegado a la República Dominicana a mediados del siglo XIX.', 'era un español llegado a la República Dominicana — a mediados del siglo XIX, según la casa, que sitúa allí los orígenes de la empresa; a finales de la década de 1880, según un artículo de la Premium Cigar Association de abril de 2024.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('war ein Spanier, der Mitte des 19. Jahrhunderts in die Dominikanische Republik kam.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'war ein Spanier, der Mitte des 19. Jahrhunderts in die Dominikanische Republik kam.', 'war ein Spanier, der in die Dominikanische Republik kam — Mitte des 19. Jahrhunderts, nach Angabe des Hauses, das dort die Ursprünge des Unternehmens ansiedelt; Ende der 1880er Jahre, laut einem Artikel der Premium Cigar Association vom April 2024.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('是十九世纪中叶抵达多米尼加共和国的西班牙人。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '是十九世纪中叶抵达多米尼加共和国的西班牙人。', '是抵达多米尼加共和国的西班牙人——据该公司称是在十九世纪中叶，公司把企业的起源定在那时；据 Premium Cigar Association 2024年4月的一篇文章，则是在 1880年代末。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('إسبانيًا وصل إلى الجمهورية الدومينيكية في منتصف القرن التاسع عشر.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'إسبانيًا وصل إلى الجمهورية الدومينيكية في منتصف القرن التاسع عشر.', 'إسبانيًا وصل إلى الجمهورية الدومينيكية — في منتصف القرن التاسع عشر بحسب الدار، التي تضع هناك أصول الشركة؛ وفي أواخر ثمانينيات القرن التاسع عشر بحسب مقال لـ Premium Cigar Association في أبريل 2024.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera Palma';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Aging Room et Swag pour Rafael Nodal, et la Matilde que cet atlas porte déjà.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Aging Room et Swag pour Rafael Nodal, et la Matilde que cet atlas porte déjà.', 'Aging Room et Swag pour Rafael Nodal — mais La Bohème et la Quattro Nicaragua d''Aging Room sont faites, depuis 2025, chez A.J. Fernandez, au Nicaragua —, et la Matilde que cet atlas porte déjà.'), `history`),
  `history_en` = IF(LOCATE(CAST('Aging Room and Swag for Rafael Nodal, and the Matilde this atlas already holds.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Aging Room and Swag for Rafael Nodal, and the Matilde this atlas already holds.', 'Aging Room and Swag for Rafael Nodal (but La Bohème and Aging Room''s Quattro Nicaragua have been made, since 2025, at A.J. Fernandez, in Nicaragua), and the Matilde this atlas already holds.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Aging Room y Swag para Rafael Nodal, y la Matilde que este atlas ya recoge.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Aging Room y Swag para Rafael Nodal, y la Matilde que este atlas ya recoge.', 'Aging Room y Swag para Rafael Nodal — pero La Bohème y la Quattro Nicaragua de Aging Room se hacen, desde 2025, en A.J. Fernandez, en Nicaragua —, y la Matilde que este atlas ya recoge.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Aging Room und Swag für Rafael Nodal, und die Matilde, die dieser Atlas bereits führt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Aging Room und Swag für Rafael Nodal, und die Matilde, die dieser Atlas bereits führt.', 'Aging Room und Swag für Rafael Nodal — doch La Bohème und die Quattro Nicaragua von Aging Room werden seit 2025 bei A.J. Fernandez in Nicaragua gefertigt —, und die Matilde, die dieser Atlas bereits führt.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('为 Rafael Nodal 生产 Aging Room 与 Swag，还有本图集已收录的 Matilde。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '为 Rafael Nodal 生产 Aging Room 与 Swag，还有本图集已收录的 Matilde。', '为 Rafael Nodal 生产 Aging Room 与 Swag（但 Aging Room 的 La Bohème 与 Quattro Nicaragua 自 2025年起由尼加拉瓜的 A.J. Fernandez 制造），还有本图集已收录的 Matilde。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('«إيجينغ روم» و«سواغ» لرافاييل نودال، و«ماتيلدي» التي يضمّها هذا الأطلس.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '«إيجينغ روم» و«سواغ» لرافاييل نودال، و«ماتيلدي» التي يضمّها هذا الأطلس.', 'Aging Room وSwag لرافاييل نودال — غير أنّ La Bohème وQuattro Nicaragua من Aging Room تُصنعان منذ 2025 لدى A.J. Fernandez في نيكاراغوا —، وMatilde التي يضمّها هذا الأطلس.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera Palma';

UPDATE `brands` SET
  `founded` = '1925 (création), 1936 (enregistrement) — Tamboril',
  `gamme` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"La marque propre de la fabrique, et la seule qu''elle signe de son nom. Le mot désigne l''atelier de roulage lui-même — la salle où les torcedores travaillent en rangs.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Assemblages dominicains, capes variées"},{"name":"Rough Rider","color":"#C9A96E","force":null,"story":"Marque de Jochy Blanco, venue du portefeuille d''IndianHead qu''il a racheté en 2015 à Bill Bock ; la ligne Rough Rider Sweets compte trois cigares, Connecticut, Maduro et Candela, ce dernier présenté au PCA 2025 en Robusto (5 x 50), Toro (6 x 52) et Gordo (6 x 60), tripe de Criollo 98, Piloto Cubano et Cameroun, roulé à Tabacalera Palma. Un article de la Premium Cigar Association d''avril 2024 la décrit en longfiller, à bout sucré.","vitolas":[],"wrapper":"Connecticut, maduro, candela"},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","story":"Parue en 2007 selon cigarcentury.com, qui la dit faite par Tabacalera Palma, avec liant dominicain et tripe du Nicaragua et de République dominicaine ; entrée en 2015 chez Jochy Blanco avec le rachat d''IndianHead. En avril 2024, un article de la Premium Cigar Association la range parmi les lignes à tripe mixte (mixed-fill) de la fabrique, vendue en boîtes ; en octobre 2026, Neptune Cigar vend le Connecticut Robusto comme cigare « Handmade », fabricant Tabacalera Palma.","vitolas":[],"wrapper":"Connecticut, habano, maduro"},{"name":"La Instructora","color":"#6B4226","force":"Medium","story":"Projet commun de Jochy Blanco, qui en a assemblé la Delicado, et d''Aaron Saide, nommé son fondateur par luxurycigarclub.com ; sur le marché depuis 2017, roulée à Tabacalera Palma, avec la Box Pressed (cape Cubra du Brésil, liant Piloto, tripe de Criollo 98 et de Piloto dominicains) et la Delicado (cape Connecticut américain). En avril 2024, un article de la Premium Cigar Association la range parmi les marques haut de gamme de la fabrique.","vitolas":[],"wrapper":"Cubra brésilien, Connecticut"}]',
  `gamme_en` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"The factory''s own brand, and the only one it signs with its own name. The word names the rolling floor itself — the room where the torcedores work in rows.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Dominican blends, varied wrappers"},{"name":"Rough Rider","color":"#C9A96E","force":null,"story":"A brand of Jochy Blanco, coming from the IndianHead portfolio that he bought in 2015 from Bill Bock; the Rough Rider Sweets line has three cigars, Connecticut, Maduro and Candela, the last shown at PCA 2025 in Robusto (5 x 50), Toro (6 x 52) and Gordo (6 x 60), with a filler of Criollo 98, Piloto Cubano and Cameroon, rolled at Tabacalera Palma. An article by the Premium Cigar Association of April 2024 describes it as longfiller, with a sweet tip.","vitolas":[],"wrapper":"Connecticut, maduro, candela"},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","story":"Released in 2007 according to cigarcentury.com, which says it is made by Tabacalera Palma, with a Dominican binder and a filler from Nicaragua and the Dominican Republic; it came to Jochy Blanco in 2015 with the purchase of IndianHead. In April 2024, an article by the Premium Cigar Association places it among the factory''s mixed-filler lines (mixed-fill), sold in boxes; in October 2026, Neptune Cigar sells the Connecticut Robusto as a “Handmade” cigar, manufacturer Tabacalera Palma.","vitolas":[],"wrapper":"Connecticut, habano, maduro"},{"name":"La Instructora","color":"#6B4226","force":"Medium","story":"A joint project of Jochy Blanco, who blended the Delicado, and Aaron Saide, named its founder by luxurycigarclub.com; on the market since 2017, rolled at Tabacalera Palma, with the Box Pressed (Cubra wrapper from Brazil, Piloto binder, filler of Dominican Criollo 98 and Piloto) and the Delicado (American Connecticut wrapper). In April 2024, an article by the Premium Cigar Association places it among the factory''s high-end brands.","vitolas":[],"wrapper":"Brazilian Cubra, Connecticut"}]',
  `gamme_es` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"La marca propia de la fábrica, y la única que firma con su nombre. La palabra designa la propia sala de liado: el lugar donde los torcedores trabajan en filas.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Ligadas dominicanas, capas variadas"},{"name":"Rough Rider","color":"#C9A96E","force":null,"story":"Marca de Jochy Blanco, procedente de la cartera de IndianHead, que compró en 2015 a Bill Bock; la línea Rough Rider Sweets cuenta con tres puros, Connecticut, Maduro y Candela, este último presentado en el PCA 2025 en Robusto (5 x 50), Toro (6 x 52) y Gordo (6 x 60), con tripa de Criollo 98, Piloto Cubano y Camerún, enrollado en Tabacalera Palma. Un artículo de la Premium Cigar Association de abril de 2024 la describe como longfiller, de perilla endulzada.","vitolas":[],"wrapper":"Connecticut, maduro, candela"},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","story":"Aparecida en 2007 según cigarcentury.com, que la dice hecha por Tabacalera Palma, con capote dominicano y tripa de Nicaragua y de República Dominicana; pasó en 2015 a Jochy Blanco con la compra de IndianHead. En abril de 2024, un artículo de la Premium Cigar Association la sitúa entre las líneas de tripa mixta (mixed-fill) de la fábrica, vendida en cajas; en octubre de 2026, Neptune Cigar vende el Connecticut Robusto como puro «Handmade», fabricante Tabacalera Palma.","vitolas":[],"wrapper":"Connecticut, habano, maduro"},{"name":"La Instructora","color":"#6B4226","force":"Medium","story":"Proyecto conjunto de Jochy Blanco, que realizó la mezcla de la Delicado, y de Aaron Saide, nombrado su fundador por luxurycigarclub.com; en el mercado desde 2017, enrollada en Tabacalera Palma, con la Box Pressed (capa Cubra de Brasil, capote Piloto, tripa de Criollo 98 y de Piloto dominicanos) y la Delicado (capa Connecticut estadounidense). En abril de 2024, un artículo de la Premium Cigar Association la sitúa entre las marcas de gama alta de la fábrica.","vitolas":[],"wrapper":"Cubra brasileño, Connecticut"}]',
  `gamme_de` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"Die eigene Marke der Fabrik und die einzige, die sie mit ihrem Namen zeichnet. Das Wort bezeichnet den Rollsaal selbst — den Raum, in dem die Torcedores in Reihen arbeiten.","vitolas":["Robusto","Toro","Corona"],"wrapper":"Dominikanische Mischungen, wechselnde Deckblätter"},{"name":"Rough Rider","color":"#C9A96E","force":null,"story":"Marke von Jochy Blanco, aus dem Portfolio von IndianHead stammend, das er 2015 von Bill Bock erworben hat; die Linie Rough Rider Sweets umfasst drei Zigarren, Connecticut, Maduro und Candela, Letztere auf der PCA 2025 vorgestellt in Robusto (5 x 50), Toro (6 x 52) und Gordo (6 x 60), Einlage aus Criollo 98, Piloto Cubano und Kamerun, gerollt bei Tabacalera Palma. Ein Artikel der Premium Cigar Association vom April 2024 beschreibt sie als longfiller mit gesüßtem Mundstück.","vitolas":[],"wrapper":"Connecticut, Maduro, Candela"},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","story":"Laut cigarcentury.com 2007 erschienen; die Seite sagt, sie werde von Tabacalera Palma hergestellt, mit dominikanischem Umblatt und Einlage aus Nicaragua und der Dominikanischen Republik; 2015 mit dem Kauf von IndianHead zu Jochy Blanco gekommen. Im April 2024 ordnet ein Artikel der Premium Cigar Association sie unter die Linien mit gemischter Einlage (mixed-fill) der Fabrik ein, in Schachteln verkauft; im Oktober 2026 verkauft Neptune Cigar den Connecticut Robusto als Zigarre „Handmade“, Hersteller Tabacalera Palma.","vitolas":[],"wrapper":"Connecticut, Habano, Maduro"},{"name":"La Instructora","color":"#6B4226","force":"Medium","story":"Gemeinschaftsprojekt von Jochy Blanco, der die Mischung der Delicado zusammengestellt hat, und von Aaron Saide, den luxurycigarclub.com als ihren Gründer nennt; seit 2017 auf dem Markt, bei Tabacalera Palma gerollt, mit der Box Pressed (Deckblatt Cubra aus Brasilien, Umblatt Piloto, Einlage aus dominikanischem Criollo 98 und Piloto) und der Delicado (Deckblatt Connecticut aus den USA). Im April 2024 ordnet ein Artikel der Premium Cigar Association sie unter die hochwertigen Marken der Fabrik ein.","vitolas":[],"wrapper":"Cubra (Brasilien), Connecticut"}]',
  `gamme_zh` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"工厂的自有品牌，也是它唯一以自己名字署名的品牌。这个词本指卷制车间——卷烟师成排工作的那间屋子。","vitolas":["Robusto","Toro","Corona"],"wrapper":"多米尼加配方，茄衣不一"},{"name":"Rough Rider","color":"#C9A96E","force":null,"story":"Jochy Blanco的品牌，源自IndianHead的产品组合，他于2015年自Bill Bock处收购；Rough Rider Sweets产品线共有三款雪茄，即Connecticut、Maduro和Candela，其中Candela在PCA 2025上亮相，规格为Robusto（5 x 50）、Toro（6 x 52）和Gordo（6 x 60），茄芯为Criollo 98、Piloto Cubano和喀麦隆烟叶，在Tabacalera Palma卷制。据Premium Cigar Association 2024年四月的一篇文章，它被描述为longfiller，带甜头。","vitolas":[],"wrapper":"Connecticut、maduro、candela"},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","story":"据cigarcentury.com，2007年面世，该网站称其由Tabacalera Palma制造，茄套为多米尼加产，茄芯来自尼加拉瓜和多米尼加共和国；2015年随收购IndianHead而来到Jochy Blanco处。2024年四月，Premium Cigar Association的一篇文章将其列入该工厂的混合茄芯（mixed-fill）产品线，以盒装销售；2026年十月，Neptune Cigar将Connecticut Robusto作为「Handmade」雪茄销售，制造商为Tabacalera Palma。","vitolas":[],"wrapper":"Connecticut、habano、maduro"},{"name":"La Instructora","color":"#6B4226","force":"Medium","story":"Jochy Blanco与Aaron Saide的共同项目，前者调配了Delicado，后者被luxurycigarclub.com称为其创始人；2017年起上市，在Tabacalera Palma卷制，包括Box Pressed（巴西Cubra茄衣、Piloto茄套、多米尼加Criollo 98与Piloto茄芯）和Delicado（美国Connecticut茄衣）。2024年四月，Premium Cigar Association的一篇文章将其列入该工厂的高端品牌。","vitolas":[],"wrapper":"巴西Cubra、Connecticut"}]',
  `gamme_ar` = '[{"name":"La Galera","color":"#8B5A2B","force":"Medium","story":"العلامة الخاصة بالمصنع، والوحيدة التي يوقّعها باسمه. والكلمة تسمّي قاعة اللفّ نفسها — الغرفة التي يعمل فيها اللافّون صفوفًا.","vitolas":["Robusto","Toro","Corona"],"wrapper":"مزائج دومينيكية بأغلفة متنوّعة"},{"name":"Rough Rider","color":"#C9A96E","force":null,"story":"علامة تعود إلى Jochy Blanco، آتية من محفظة IndianHead التي اشتراها في 2015 من Bill Bock؛ يضم خط Rough Rider Sweets ثلاث سيجارات، Connecticut وMaduro وCandela، وقد قُدّمت الأخيرة في PCA 2025 بمقاسات Robusto (5 x 50) وToro (6 x 52) وGordo (6 x 60)، بحشوة من Criollo 98 وPiloto Cubano والكاميرون، وتُلَفّ في Tabacalera Palma. ويصفها مقال لـ Premium Cigar Association في أبريل 2024 بأنها longfiller ذات رأس محلّى.","vitolas":[],"wrapper":"Connecticut وmaduro وcandela"},{"name":"Cuban Aristocrat","color":"#8B5A2B","force":"Mild-Medium","story":"ظهرت في 2007 بحسب cigarcentury.com الذي يقول إنها من صنع Tabacalera Palma، برابط دومينيكي وحشوة من نيكاراغوا وجمهورية الدومينيكان؛ وانتقلت في 2015 إلى Jochy Blanco مع شراء IndianHead. وفي أبريل 2024 يدرجها مقال لـ Premium Cigar Association ضمن خطوط الحشوة المختلطة (mixed-fill) في المصنع، وتُباع في علب؛ وفي أكتوبر 2026 يبيع Neptune Cigar الـConnecticut Robusto بوصفه سيجارًا «Handmade»، والجهة المصنّعة Tabacalera Palma.","vitolas":[],"wrapper":"Connecticut وhabano وmaduro"},{"name":"La Instructora","color":"#6B4226","force":"Medium","story":"مشروع مشترك بين Jochy Blanco، الذي أعدّ توليفة Delicado، وAaron Saide، الذي يسميه luxurycigarclub.com مؤسسها؛ في السوق منذ 2017، وتُلَفّ في Tabacalera Palma، وتضم Box Pressed (غلاف خارجي Cubra من البرازيل، ورابط Piloto، وحشوة من Criollo 98 وPiloto دومينيكيين) وDelicado (غلاف خارجي Connecticut أمريكي). وفي أبريل 2024 يدرجها مقال لـ Premium Cigar Association ضمن علامات المصنع الراقية.","vitolas":[],"wrapper":"Cubra برازيلي وConnecticut"}]',
  `source` = IF(LOCATE(CAST('tabacalerapalma.com « About Us » (octobre 2026 : José Arnald' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'tabacalerapalma.com « About Us » (octobre 2026 : José Arnaldo Blanco II a établi Tabacalera Palma en 1925 et déposé son enregistrement industriel en 1936 ; origines de l''entreprise au milieu du XIXe siècle ; accueil : « depuis 1936 ») ; premiumcigars.org « La Galera Cigars: Grounded in the Past, Looking Toward the Future » (15 avril 2024 : établie en 1925, reconnaissance industrielle en 1936 ; José Manuel Blanco Lozada émigré d''Espagne à la fin des années 1880 ; cigares faits à la main pour Matilde, Aging Room, Kristoff, Villiger, Senorial ; Swag et Rafael Nodal non cités) ; cigar-coop.com « Tabacalera Palma » (1er mars 2026 : en activité depuis 1936, quatre-vingt-dixième anniversaire cette année ; marque propre La Galera) ; cigar-coop.com « La Boheme Reintroduced Under Aging Room Cigars » (4 décembre 2024 : version d''origine à Tabacalera Palma, nouvelle version chez A.J. Fernandez, au Nicaragua) ; cigar-coop.com « PCA 2025: Aging Room Cigars » (17 mai 2025 : Quattro Nicaragua chez A.J. Fernandez, au Nicaragua ; La Bohème passée chez A.J. Fernandez) ; neptunecigar.com « Cuban Aristocrat Connecticut Robusto » (octobre 2026 : « Handmade », fabricant Tabacalera Palma, République dominicaine, cape Connecticut Shade d''Équateur, tripe dominicaine et nicaraguayenne ; en stock)')),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacalera Palma';

-- ── Tabacosta ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Momentohumo.com lui compte quatre marques propres' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Momentohumo.com lui compte quatre marques propres', 'Momentohumo.com, dans une page du 2 juin 2017, lui compte quatre marques propres'), `history`),
  `history_en` = IF(LOCATE(CAST('Momentohumo.com credits it with four brands of its own' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Momentohumo.com credits it with four brands of its own', 'Momentohumo.com, in a page of 2 June 2017, credits it with four brands of its own'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Momentohumo.com le atribuye cuatro marcas propias' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'Momentohumo.com le atribuye cuatro marcas propias', 'Momentohumo.com, en una página del 2 de junio de 2017, le atribuye cuatro marcas propias'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Momentohumo.com rechnet ihm vier eigene Marken zu' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Momentohumo.com rechnet ihm vier eigene Marken zu', 'Momentohumo.com rechnet ihm auf einer Seite vom 2. Juni 2017 vier eigene Marken zu'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Momentohumo.com 列出其四个自有品牌' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, 'Momentohumo.com 列出其四个自有品牌', 'Momentohumo.com 在2017年6月2日的一个页面中列出其四个自有品牌'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('ويحصي لها Momentohumo.com أربع علامات خاصة' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'ويحصي لها Momentohumo.com أربع علامات خاصة', 'ويحصي لها Momentohumo.com، في صفحة بتاريخ 2 يونيو 2017، أربع علامات خاصة'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacosta';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('En septembre 2026, Cigarworld.de vend encore des Manuel Alonso en Montescos, Nicaragua Robusto et VI.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'En septembre 2026, Cigarworld.de vend encore des Manuel Alonso en Montescos, Nicaragua Robusto et VI.', 'En octobre 2026, le site tabacosta.com, dont la page About est datée du 9 septembre 2025, présente la maison sous le nom de Costa Cigars : des cigares faits à la main à Estelí, une adresse au barrio El Rosario et des photos de la fabrique, sans nommer aucune marque ni aucune ligne. Humoytabaco.com écrit en novembre 2024 ne pas savoir si la marque Manuel Alonso est encore sur le marché.'), `history`),
  `history_en` = IF(LOCATE(CAST('In September 2026, Cigarworld.de still sells Manuel Alonso in Montescos, Nicaragua Robusto and VI.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'In September 2026, Cigarworld.de still sells Manuel Alonso in Montescos, Nicaragua Robusto and VI.', 'In October 2026, the site tabacosta.com, whose About page is dated 9 September 2025, presents the house under the name Costa Cigars: handmade cigars in Estelí, an address in the barrio El Rosario and photos of the factory, without naming any brand or any line. Humoytabaco.com writes in November 2024 that it does not know whether the Manuel Alonso brand is still on the market.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('En septiembre de 2026, Cigarworld.de sigue vendiendo Manuel Alonso en Montescos, Nicaragua Robusto y VI.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'En septiembre de 2026, Cigarworld.de sigue vendiendo Manuel Alonso en Montescos, Nicaragua Robusto y VI.', 'En octubre de 2026, el sitio tabacosta.com, cuya página About lleva fecha del 9 de septiembre de 2025, presenta a la casa con el nombre de Costa Cigars: puros hechos a mano en Estelí, una dirección en el barrio El Rosario y fotos de la fábrica, sin nombrar ninguna marca ni ninguna línea. Humoytabaco.com escribe en noviembre de 2024 que no sabe si la marca Manuel Alonso sigue en el mercado.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Im September 2026 verkauft Cigarworld.de weiterhin Manuel Alonso in Montescos, Nicaragua Robusto und VI.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Im September 2026 verkauft Cigarworld.de weiterhin Manuel Alonso in Montescos, Nicaragua Robusto und VI.', 'Im Oktober 2026 stellt die Website tabacosta.com, deren About-Seite auf den 9. September 2025 datiert ist, das Haus unter dem Namen Costa Cigars vor: handgefertigte Zigarren in Estelí, eine Adresse im Barrio El Rosario und Fotos der Fabrik, ohne irgendeine Marke oder Linie zu nennen. Humoytabaco.com schreibt im November 2024, es wisse nicht, ob die Marke Manuel Alonso noch auf dem Markt sei.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('2026年9月，Cigarworld.de 仍在销售 Manuel Alonso，规格为 Montescos、Nicaragua Robusto 与 VI。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '2026年9月，Cigarworld.de 仍在销售 Manuel Alonso，规格为 Montescos、Nicaragua Robusto 与 VI。', '2026年10月，tabacosta.com 网站（其 About 页面标注日期为2025年9月9日）以 Costa Cigars 之名介绍该公司：在埃斯特利手工制作的雪茄、位于 El Rosario 街区的地址和工厂照片，没有点出任何品牌或系列。Humoytabaco.com 在2024年11月写道，不清楚 Manuel Alonso 品牌是否仍在市场上。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('وفي سبتمبر 2026، لا يزال Cigarworld.de يبيع Manuel Alonso بقياسات Montescos وNicaragua Robusto وVI.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'وفي سبتمبر 2026، لا يزال Cigarworld.de يبيع Manuel Alonso بقياسات Montescos وNicaragua Robusto وVI.', 'وفي أكتوبر 2026 يقدّم موقع tabacosta.com، الذي تحمل صفحة About فيه تاريخ 9 سبتمبر 2025، الدارَ باسم Costa Cigars: سيجار مصنوع يدويًا في إستيلي، وعنوانًا في حيّ El Rosario، وصورًا للمصنع، من دون أن يذكر أيّ علامة ولا أيّ خطّ. ويكتب Humoytabaco.com في نوفمبر 2024 أنّه لا يعرف إن كانت علامة Manuel Alonso لا تزال في السوق.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacosta';

UPDATE `brands` SET
  `gamme` = '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","story":"Assemblage entièrement nicaraguayen (Condega, Estelí, Jalapa), de force moyenne à corsée, dit Momentohumo.com dans une page du 2 juin 2017 consacrée au Pirámides. En octobre 2026, le site de la maison, ouvert en septembre 2025, porte le nom de Costa Cigars sans détailler de ligne.","vitolas":[],"wrapper":"Nicaragua (Condega)"}]',
  `gamme_en` = '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","story":"Entirely Nicaraguan blend (Condega, Estelí, Jalapa), of medium to full strength, says Momentohumo.com in a page of 2 June 2017 devoted to the Pirámides. In October 2026, the house''s website, opened in September 2025, bears the name Costa Cigars without detailing any line.","vitolas":[],"wrapper":"Nicaragua (Condega)"}]',
  `gamme_es` = '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","story":"Liga enteramente nicaragüense (Condega, Estelí, Jalapa), de fuerza media a fuerte, dice Momentohumo.com en una página del 2 de junio de 2017 dedicada al Pirámides. En octubre de 2026, el sitio de la casa, abierto en septiembre de 2025, lleva el nombre de Costa Cigars sin detallar ninguna línea.","vitolas":[],"wrapper":"Nicaragua (Condega)"}]',
  `gamme_de` = '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","story":"Vollständig nicaraguanische Mischung (Condega, Estelí, Jalapa), von mittlerer bis kräftiger Stärke, so Momentohumo.com auf einer Seite vom 2. Juni 2017, die dem Pirámides gewidmet ist. Im Oktober 2026 trägt die Website des Hauses, im September 2025 eröffnet, den Namen Costa Cigars, ohne eine Linie näher zu beschreiben.","vitolas":[],"wrapper":"Nicaragua (Condega)"}]',
  `gamme_zh` = '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","story":"完全产自尼加拉瓜的拼配（孔德加、埃斯特利、哈拉帕），强度中等至浓烈，据 Momentohumo.com 在2017年6月2日一个专门介绍 Pirámides 的页面中所述。2026年10月，该公司于2025年9月开通的网站以 Costa Cigars 为名，没有细列任何系列。","vitolas":[],"wrapper":"尼加拉瓜（孔德加）"}]',
  `gamme_ar` = '[{"name":"Costa","color":"#A0522D","force":"Medium-Full","story":"خلطة نيكاراغوية بالكامل (كونديغا وإستيلي وخالابا)، متوسطة القوة إلى قوية، بحسب Momentohumo.com في صفحة بتاريخ 2 يونيو 2017 مخصّصة لـPirámides. وفي أكتوبر 2026 يحمل موقع الدار، المفتوح في سبتمبر 2025، اسم Costa Cigars من دون تفصيل أيّ خطّ.","vitolas":[],"wrapper":"نيكاراغوا (كونديغا)"}]',
  `source` = IF(LOCATE(CAST('cigarworld.de « Manuel Alonso Bundle » (consulté le 25 septembre 2026, lu directement : en septembre 2026, les formats Montescos, Nicaragua Robusto et VI sont en vente, d''autres formats étant épuisés)' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'cigarworld.de « Manuel Alonso Bundle » (consulté le 25 septembre 2026, lu directement : en septembre 2026, les formats Montescos, Nicaragua Robusto et VI sont en vente, d''autres formats étant épuisés)', 'cigarworld.de « Manuel Alonso Bundle » (8 octobre 2026 : série au catalogue depuis le 3 novembre 2016, importateur Tabac Benden GmbH, aucun fabricant nommé, ni Tabacosta ni Gran Selección ; Montescos en reliquat et article abandonné, Nicaragua Robusto et VI à la vente)'), `source`),
  `source` = IF(LOCATE(CAST('tabacosta.com « costa cigars – Handmade Cigars from Esteli, ' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'tabacosta.com « costa cigars – Handmade Cigars from Esteli, Nicaragua » et « About » (8 octobre 2026 : site WordPress dont la page About est datée du 9 septembre 2025, images du 10 septembre 2025 ; maison nommée Costa Cigars, cigares faits à la main à Estelí, adresse barrio El Rosario ; aucune marque ni ligne nommée) ; momentohumo.com « Hoy toca… COSTA Pirámides » (2 juin 2017 : fondateurs, usine, quatre marques propres, blend du Pirámides) ; humoytabaco.com « Manuel Alonso » (25 novembre 2024 : l''auteur ignore si la marque est encore sur le marché) ; humoytabaco.com « Manuel Alonso – Gran Selección (Conde) » (9 septembre 2020 : critique d''un Conde acheté en Espagne, fabricant N/D, pas de vente)')),
  `updated_at` = NOW()
 WHERE `name` = 'Tabacosta';

-- ── Villiger ──
UPDATE `brands` SET
  `factory` = 'Villiger Söhne AG, Pfeffikon (Suisse) ; Villiger de Nicaragua, Estelí (coentreprise avec Joya selon la presse de 2021) ; ABAM, Santo Domingo ; Tabacalera Palma (RD, série Cuéllar)',
  `gamme` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"Puro entièrement nicaraguayen sorti en Europe en 1998, qui reprend le nom d''une fabrique havanaise du XIXe siècle, disent Cigar Coop et Blind Man''s Puff en mars 2019 ; Cigar Coop le dit alors roulé chez Joya de Nicaragua, à Estelí. Cigarworld.de, détaillant allemand, donne en octobre 2026 une cape H-2000, un liant Connecticut et une tripe, tous du Nicaragua, en longfiller. Villiger la compte parmi les marques de son usine d''Estelí, achevée fin septembre 2021, et Noblego.de, autre détaillant allemand, la tient en stock en octobre 2026.","wrapper":"Nicaragua (H-2000)"},{"name":"Cuéllar","color":"#5C3317","story":"Série de trois cigares dominicains, Connecticut Krēmē, Black Forest et Caribe, produite par Tabacalera Palma, la fabrique de Jochy Blanco en République dominicaine, disent Cigar Coop en 2019, en janvier 2025 et en mai 2025. Black Forest, annoncé en octobre 2019, a une cape maduro sur liant et tripe dominicains ; Caribe, annoncé le 31 janvier 2025, une cape habano d''Équateur sur liant et tripe dominicains. En octobre 2026, Neptune Cigar vend le Caribe en stock et le dit fait chez Tabacalera La Palma.","wrapper":"Connecticut / Maduro / Habano"},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"Un nom de vieille marque cubaine, relancé par Villiger en 2007 comme cigare dominicain, roulé à l''ABAM, la fabrique de Santo Domingo que Cigar Coop dit en mars 2018 propriété de José « Matias » Maragoto et chargée de rouler les cigares dominicains de Villiger.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"Ligne de République dominicaine que la page de la maison, en octobre 2026, dit légère à moyenne et abordable, de niveau 2 sur 5 sur l''échelle de Villiger, en cinq formats : Perla, Corona, Robusto, Torpedo et Churchill. Cigarworld.de, détaillant allemand, la dit roulée à la main en longfiller à ABAM Cigars, en bundles, sous une cape Connecticut Shade d''Équateur, avec un liant d''Indonésie et une tripe Piloto de République dominicaine et du Nicaragua ; la marque date du début des années 2000 selon ce détaillant, qui la tient à son catalogue, pour la Corona, depuis le 7 décembre 2010.","vitolas":[],"wrapper":"Connecticut Shade (Équateur)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"Présentée en 2014 par Villiger selon Cigarworld.de, qui la tient à son catalogue depuis le 12 août 2014 et la dit roulée à la main en mediumfiller, sous une cape H-2000 d''Équateur, avec un liant d''Indonésie et une tripe du Nicaragua. Villiger la compte parmi les marques de son usine d''Estelí, achevée fin septembre 2021 ; en octobre 2026, la page de la maison donne cinq formats d''origine Nicaragua (Perla, Corona, Robusto, Torpedo, Churchill), de niveau 4 sur 5 sur son échelle.","vitolas":[],"wrapper":"Équateur (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"Apparue au début des années 2000 chez Liberty Cigar Company, en Allemagne, puis entrée dans le groupe Villiger, elle a quitté le Honduras, où Plasencia la roulait, puis la République dominicaine, où ABAM la roulait, pour Estelí : un nouveau mélange, cape criollo du Nicaragua, liant du Cibao dominicain, tripe nicaraguayenne de Jalapa et d''Estelí, est montré en janvier 2022 au salon TPE de Las Vegas, en Corona, Robusto et Gran Toro. En octobre 2026, la page de la maison la range parmi ses cigares faits à la main, en quatre formats (Gordito, Robusto, Corona, Gran Toro) de niveau 4 sur 5 sur son échelle.","vitolas":[],"wrapper":"Criollo (Nicaragua)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"Relancée en 2025 avec un nouveau mélange, cape Connecticut Shade d''Équateur, liant du Nicaragua, tripe du Nicaragua et de République dominicaine, annoncée au salon PCA en avril 2025 en Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) et Churchill (7 x 50) ; la version précédente avait une cape habano, dit un compte rendu de juillet 2026. Cigarworld.de la dit roulée à la main en longfiller à Estelí par Tabacalera Villiger de Nicaragua, dans les locaux de Joya de Nicaragua, et la tient à son catalogue depuis le 28 août 2025 ; en octobre 2026, la page de la maison donne Robusto, Toro et Churchill, de niveau 2 sur 5 sur son échelle.","vitolas":[],"wrapper":"Connecticut (Équateur)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"Lancée en Europe en mai 2017 en deux versions, Honduras (roulée à Danlí par Nestor A. Plasencia, dit un compte rendu de lancement) et République dominicaine (faite à ABAM, dit un autre compte rendu), en Robusto+ (5 x 56) et Toro+ (6 x 52). En octobre 2026, la page de la maison la présente en quatre origines, Honduras, République dominicaine, Nicaragua et Brésil, de niveau 4, 2,5, 5 et 3,5 sur 5 sur son échelle, et la destine aux amateurs de cigares roulés à la main ; Villiger compte Corrida parmi les marques de son usine d''Estelí, achevée fin septembre 2021.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"Série présentée à InterTabac 2023, à Dortmund, selon Cigarworld.de, qui la dit roulée à la main en longfiller à Estelí en partenariat avec Joya de Nicaragua, cape et tripe du Nicaragua sur un liant d''Indonésie, et la tient à son catalogue depuis le 25 septembre 2023 pour le 5 x 52. En octobre 2026, la page de la maison donne trois formats nommés par leurs dimensions, 4 x 56, 5 x 52 et 6 x 54, de niveau 4 sur 5 sur son échelle ; un aperçu d''avril 2013 présentait déjà sous ce nom une ligne à trois capes.","vitolas":[],"wrapper":"Nicaragua"}]',
  `gamme_en` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"An entirely Nicaraguan puro released in Europe in 1998, taking the name of a nineteenth-century Havana factory, say Cigar Coop and Blind Man''s Puff in March 2019; Cigar Coop then says it is rolled at Joya de Nicaragua, in Estelí. Cigarworld.de, a German retailer, gives in October 2026 an H-2000 wrapper, a Connecticut binder and a filler, all from Nicaragua, in longfiller. Villiger counts it among the brands of its factory in Estelí, completed at the end of September 2021, and Noblego.de, another German retailer, has it in stock in October 2026.","wrapper":"Nicaragua (H-2000)"},{"name":"Cuéllar","color":"#5C3317","story":"A series of three Dominican cigars, Connecticut Krēmē, Black Forest and Caribe, produced by Tabacalera Palma, Jochy Blanco''s factory in the Dominican Republic, say Cigar Coop in 2019, in January 2025 and in May 2025. Black Forest, announced in October 2019, has a maduro wrapper over a Dominican binder and filler; Caribe, announced on 31 January 2025, an Ecuadorian habano wrapper over a Dominican binder and filler. In October 2026, Neptune Cigar sells the Caribe as in stock and says it is made at Tabacalera La Palma.","wrapper":"Connecticut / Maduro / Habano"},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"An old Cuban brand name, relaunched by Villiger in 2007 as a Dominican cigar, rolled at ABAM, the Santo Domingo factory that Cigar Coop, in March 2018, says is owned by José “Matias” Maragoto and tasked with rolling Villiger''s Dominican cigars.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"A line from the Dominican Republic that the company''s page, in October 2026, calls light to medium and affordable, at level 2 of 5 on Villiger''s scale, in five sizes: Perla, Corona, Robusto, Torpedo and Churchill. Cigarworld.de, a German retailer, says it is hand-rolled longfiller at ABAM Cigars, in bundles, under a Connecticut Shade wrapper from Ecuador, with a binder from Indonesia and a Piloto filler from the Dominican Republic and Nicaragua; the brand dates from the early 2000s according to that retailer, which has carried it in its catalogue, for the Corona, since 7 December 2010.","vitolas":[],"wrapper":"Connecticut Shade (Ecuador)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"Presented in 2014 by Villiger, according to Cigarworld.de, which has carried it in its catalogue since 12 August 2014 and says it is hand-rolled mediumfiller, under an H-2000 wrapper from Ecuador, with a binder from Indonesia and a filler from Nicaragua. Villiger counts it among the brands of its factory in Estelí, completed at the end of September 2021; in October 2026, the company''s page gives five sizes of Nicaraguan origin (Perla, Corona, Robusto, Torpedo, Churchill), at level 4 of 5 on its scale.","vitolas":[],"wrapper":"Ecuador (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"It appeared in the early 2000s at Liberty Cigar Company, in Germany, then joined the Villiger group, and it left Honduras, where Plasencia rolled it, then the Dominican Republic, where ABAM rolled it, for Estelí: a new blend, with a criollo wrapper from Nicaragua, a binder from the Dominican Cibao and a Nicaraguan filler from Jalapa and Estelí, was shown in January 2022 at the TPE show in Las Vegas, in Corona, Robusto and Gran Toro. In October 2026, the company''s page places it among its handmade cigars, in four sizes (Gordito, Robusto, Corona, Gran Toro), at level 4 of 5 on its scale.","vitolas":[],"wrapper":"Criollo (Nicaragua)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"Relaunched in 2025 with a new blend, a Connecticut Shade wrapper from Ecuador, a binder from Nicaragua and a filler from Nicaragua and the Dominican Republic, it was announced at the PCA show in April 2025 in Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) and Churchill (7 x 50); the previous version had a habano wrapper, says a report from July 2026. Cigarworld.de says it is hand-rolled longfiller in Estelí by Tabacalera Villiger de Nicaragua, on the premises of Joya de Nicaragua, and has carried it in its catalogue since 28 August 2025; in October 2026, the company''s page gives Robusto, Toro and Churchill, at level 2 of 5 on its scale.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"Launched in Europe in May 2017 in two versions, Honduras (rolled in Danlí by Nestor A. Plasencia, says a launch report) and Dominican Republic (made at ABAM, says another report), in Robusto+ (5 x 56) and Toro+ (6 x 52). In October 2026, the company''s page presents it in four origins, Honduras, the Dominican Republic, Nicaragua and Brazil, at levels 4, 2.5, 5 and 3.5 of 5 on its scale, and aims it at enthusiasts of hand-rolled cigars; Villiger counts Corrida among the brands of its factory in Estelí, completed at the end of September 2021.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"A series presented at InterTabac 2023, in Dortmund, according to Cigarworld.de, which says it is hand-rolled longfiller in Estelí in partnership with Joya de Nicaragua, with wrapper and filler from Nicaragua and a binder from Indonesia, and has carried it in its catalogue since 25 September 2023 for the 5 x 52. In October 2026, the company''s page gives three sizes named by their dimensions, 4 x 56, 5 x 52 and 6 x 54, at level 4 of 5 on its scale; a preview from April 2013 already presented a three-wrapper line under this name.","vitolas":[],"wrapper":"Nicaragua"}]',
  `gamme_es` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"Puro enteramente nicaragüense salido en Europa en 1998, que retoma el nombre de una fábrica habanera del siglo XIX, dicen Cigar Coop y Blind Man''s Puff en marzo de 2019; Cigar Coop lo dice entonces liado en Joya de Nicaragua, en Estelí. Cigarworld.de, minorista alemán, da en octubre de 2026 una capa H-2000, un capote Connecticut y una tripa, todos de Nicaragua, en longfiller. Villiger la cuenta entre las marcas de su fábrica de Estelí, terminada a finales de septiembre de 2021, y Noblego.de, otro minorista alemán, la tiene en stock en octubre de 2026.","wrapper":"Nicaragua (H-2000)"},{"name":"Cuéllar","color":"#5C3317","story":"Serie de tres puros dominicanos, Connecticut Krēmē, Black Forest y Caribe, producida por Tabacalera Palma, la fábrica de Jochy Blanco en la República Dominicana, dice Cigar Coop en 2019, en enero de 2025 y en mayo de 2025. Black Forest, anunciado en octubre de 2019, tiene una capa maduro sobre capote y tripa dominicanos; Caribe, anunciado el 31 de enero de 2025, una capa habano de Ecuador sobre capote y tripa dominicanos. En octubre de 2026, Neptune Cigar vende el Caribe en stock y lo dice hecho en Tabacalera La Palma.","wrapper":"Connecticut / Maduro / Habano"},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"Un nombre de vieja marca cubana, relanzado por Villiger en 2007 como puro dominicano, liado en ABAM, la fábrica de Santo Domingo que Cigar Coop dice en marzo de 2018 propiedad de José «Matias» Maragoto y encargada de liar los puros dominicanos de Villiger.","vitolas":[],"wrapper":"No divulgada"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"Línea de la República Dominicana que la página de la casa, en octubre de 2026, califica de ligera a media y asequible, de nivel 2 sobre 5 en la escala de Villiger, en cinco formatos: Perla, Corona, Robusto, Torpedo y Churchill. Cigarworld.de, minorista alemán, indica que está enrollada a mano en longfiller en ABAM Cigars, en bundles, con capa Connecticut Shade de Ecuador, capote de Indonesia y tripa Piloto de la República Dominicana y de Nicaragua; la marca data de principios de los años 2000 según ese minorista, que la tiene en su catálogo, para la Corona, desde el 7 de diciembre de 2010.","vitolas":[],"wrapper":"Connecticut Shade (Ecuador)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"Presentada en 2014 por Villiger según Cigarworld.de, que la tiene en su catálogo desde el 12 de agosto de 2014 e indica que está enrollada a mano en mediumfiller, con capa H-2000 de Ecuador, capote de Indonesia y tripa de Nicaragua. Villiger la cuenta entre las marcas de su fábrica de Estelí, terminada a finales de septiembre de 2021; en octubre de 2026, la página de la casa ofrece cinco formatos de origen Nicaragua (Perla, Corona, Robusto, Torpedo, Churchill), de nivel 4 sobre 5 en su escala.","vitolas":[],"wrapper":"Ecuador (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"Surgida a principios de los años 2000 en Liberty Cigar Company, en Alemania, y después integrada en el grupo Villiger, dejó Honduras, donde la enrollaba Plasencia, y luego la República Dominicana, donde la enrollaba ABAM, para pasar a Estelí: una nueva mezcla, con capa criollo de Nicaragua, capote del Cibao dominicano y tripa nicaragüense de Jalapa y de Estelí, se mostró en enero de 2022 en el salón TPE de Las Vegas, en Corona, Robusto y Gran Toro. En octubre de 2026, la página de la casa la sitúa entre sus puros hechos a mano, en cuatro formatos (Gordito, Robusto, Corona, Gran Toro), de nivel 4 sobre 5 en su escala.","vitolas":[],"wrapper":"Criollo (Nicaragua)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"Relanzada en 2025 con una nueva mezcla, capa Connecticut Shade de Ecuador, capote de Nicaragua, tripa de Nicaragua y de la República Dominicana, anunciada en el salón PCA en abril de 2025 en Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) y Churchill (7 x 50); la versión anterior tenía una capa habano, dice una crónica de julio de 2026. Cigarworld.de indica que está enrollada a mano en longfiller en Estelí por Tabacalera Villiger de Nicaragua, en las instalaciones de Joya de Nicaragua, y la tiene en su catálogo desde el 28 de agosto de 2025; en octubre de 2026, la página de la casa ofrece Robusto, Toro y Churchill, de nivel 2 sobre 5 en su escala.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"Lanzada en Europa en mayo de 2017 en dos versiones, Honduras (enrollada en Danlí por Nestor A. Plasencia, dice una crónica del lanzamiento) y República Dominicana (hecha en ABAM, dice otra crónica), en Robusto+ (5 x 56) y Toro+ (6 x 52). En octubre de 2026, la página de la casa la presenta en cuatro orígenes, Honduras, República Dominicana, Nicaragua y Brasil, de nivel 4, 2,5, 5 y 3,5 sobre 5 en su escala, y la destina a los aficionados a los puros enrollados a mano; Villiger cuenta Corrida entre las marcas de su fábrica de Estelí, terminada a finales de septiembre de 2021.","vitolas":[],"wrapper":"No divulgada"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"Serie presentada en InterTabac 2023, en Dortmund, según Cigarworld.de, que indica que está enrollada a mano en longfiller en Estelí en colaboración con Joya de Nicaragua, con capa y tripa de Nicaragua sobre un capote de Indonesia, y la tiene en su catálogo desde el 25 de septiembre de 2023 para el 5 x 52. En octubre de 2026, la página de la casa ofrece tres formatos designados por sus dimensiones, 4 x 56, 5 x 52 y 6 x 54, de nivel 4 sobre 5 en su escala; un avance de abril de 2013 presentaba ya con ese nombre una línea de tres capas.","vitolas":[],"wrapper":"Nicaragua"}]',
  `gamme_de` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"Vollständig nicaraguanische Puro-Zigarre, 1998 in Europa erschienen, die den Namen einer Havanner Fabrik des 19. Jahrhunderts übernimmt, sagen Cigar Coop und Blind Man''s Puff im März 2019; Cigar Coop sagt, sie werde damals bei Joya de Nicaragua in Estelí gerollt. Cigarworld.de, ein deutscher Händler, nennt im Oktober 2026 ein H-2000-Deckblatt, ein Connecticut-Umblatt und eine Einlage, alle aus Nicaragua, als Longfiller. Villiger zählt sie zu den Marken seiner Fabrik in Estelí, Ende September 2021 fertiggestellt, und Noblego.de, ein weiterer deutscher Händler, hat sie im Oktober 2026 auf Lager.","wrapper":"Nicaragua (H-2000)"},{"name":"Cuéllar","color":"#5C3317","story":"Serie aus drei dominikanischen Zigarren, Connecticut Krēmē, Black Forest und Caribe, hergestellt von Tabacalera Palma, der Fabrik von Jochy Blanco in der Dominikanischen Republik, so Cigar Coop 2019, im Januar 2025 und im Mai 2025. Black Forest, im Oktober 2019 angekündigt, hat ein Maduro-Deckblatt auf dominikanischem Umblatt und dominikanischer Einlage; Caribe, am 31. Januar 2025 angekündigt, ein Habano-Deckblatt aus Ecuador auf dominikanischem Umblatt und dominikanischer Einlage. Im Oktober 2026 verkauft Neptune Cigar die Caribe ab Lager und sagt, sie werde bei Tabacalera La Palma gefertigt.","wrapper":"Connecticut / Maduro / Habano"},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"Ein alter kubanischer Markenname, 2007 von Villiger als dominikanische Zigarre neu lanciert, gerollt bei ABAM, der Fabrik in Santo Domingo, die nach Angabe von Cigar Coop im März 2018 José „Matias“ Maragoto gehört und damit beauftragt ist, die dominikanischen Zigarren von Villiger zu rollen.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"Eine Linie aus der Dominikanischen Republik; die Seite des Hauses nennt sie im Oktober 2026 leicht bis mittelkräftig und erschwinglich, auf Stufe 2 von 5 der Villiger-Skala, in fünf Formaten: Perla, Corona, Robusto, Torpedo und Churchill. Cigarworld.de, ein deutscher Händler, gibt an, sie sei bei ABAM Cigars als Longfiller von Hand gerollt, in Bundles, mit einem Deckblatt Connecticut Shade aus Ecuador, einem Umblatt aus Indonesien und einer Einlage Piloto aus der Dominikanischen Republik und aus Nicaragua; die Marke stammt laut diesem Händler aus dem Anfang der 2000er-Jahre, und er führt sie, für die Corona, seit dem 7. Dezember 2010 in seinem Katalog.","vitolas":[],"wrapper":"Connecticut Shade (Ecuador)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"Laut Cigarworld.de wurde sie 2014 von Villiger vorgestellt; der Händler führt sie seit dem 12. August 2014 in seinem Katalog und gibt an, sie sei als Mediumfiller von Hand gerollt, mit einem Deckblatt H-2000 aus Ecuador, einem Umblatt aus Indonesien und einer Einlage aus Nicaragua. Villiger zählt sie zu den Marken seiner Fabrik in Estelí, die Ende September 2021 fertiggestellt wurde; im Oktober 2026 nennt die Seite des Hauses fünf Formate nicaraguanischer Herkunft (Perla, Corona, Robusto, Torpedo, Churchill), auf Stufe 4 von 5 der Skala des Hauses.","vitolas":[],"wrapper":"Ecuador (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"Anfang der 2000er-Jahre bei der Liberty Cigar Company in Deutschland entstanden und dann zur Villiger-Gruppe gekommen, hat sie Honduras verlassen, wo Plasencia sie rollte, danach die Dominikanische Republik, wo ABAM sie rollte, und ist nach Estelí gezogen: Eine neue Mischung, mit einem Deckblatt criollo aus Nicaragua, einem Umblatt aus dem dominikanischen Cibao und einer nicaraguanischen Einlage aus Jalapa und Estelí, wurde im Januar 2022 auf der Messe TPE in Las Vegas gezeigt, als Corona, Robusto und Gran Toro. Im Oktober 2026 führt die Seite des Hauses sie unter ihren handgefertigten Zigarren auf, in vier Formaten (Gordito, Robusto, Corona, Gran Toro), auf Stufe 4 von 5 der Skala des Hauses.","vitolas":[],"wrapper":"Criollo (Nicaragua)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"2025 mit einer neuen Mischung neu aufgelegt, Deckblatt Connecticut Shade aus Ecuador, Umblatt aus Nicaragua, Einlage aus Nicaragua und der Dominikanischen Republik, auf der Messe PCA im April 2025 angekündigt als Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) und Churchill (7 x 50); die vorherige Version hatte ein Deckblatt habano, sagt ein Bericht vom Juli 2026. Cigarworld.de gibt an, sie sei in Estelí von Tabacalera Villiger de Nicaragua als Longfiller von Hand gerollt worden, in den Räumen von Joya de Nicaragua, und führt sie seit dem 28. August 2025 in seinem Katalog; im Oktober 2026 nennt die Seite des Hauses Robusto, Toro und Churchill, auf Stufe 2 von 5 der Skala des Hauses.","vitolas":[],"wrapper":"Connecticut (Ecuador)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"Im Mai 2017 in Europa in zwei Versionen eingeführt, Honduras (in Danlí von Nestor A. Plasencia gerollt, sagt ein Bericht zur Markteinführung) und Dominikanische Republik (bei ABAM gefertigt, sagt ein anderer Bericht), als Robusto+ (5 x 56) und Toro+ (6 x 52). Im Oktober 2026 stellt die Seite des Hauses sie in vier Herkünften vor, Honduras, Dominikanische Republik, Nicaragua und Brasilien, auf den Stufen 4, 2,5, 5 und 3,5 von 5 der Skala des Hauses, und richtet sie an Liebhaber von handgerollten Zigarren; Villiger zählt Corrida zu den Marken seiner Fabrik in Estelí, die Ende September 2021 fertiggestellt wurde.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"Eine Serie, laut Cigarworld.de auf der InterTabac 2023 in Dortmund vorgestellt; der Händler gibt an, sie sei in Estelí in Partnerschaft mit Joya de Nicaragua als Longfiller von Hand gerollt, mit Deckblatt und Einlage aus Nicaragua und einem Umblatt aus Indonesien, und führt sie seit dem 25. September 2023 für das 5 x 52 in seinem Katalog. Im Oktober 2026 nennt die Seite des Hauses drei nach ihren Maßen benannte Formate, 4 x 56, 5 x 52 und 6 x 54, auf Stufe 4 von 5 der Skala des Hauses; eine Vorschau vom April 2013 stellte unter diesem Namen bereits eine Linie mit drei Deckblättern vor.","vitolas":[],"wrapper":"Nicaragua"}]',
  `gamme_zh` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"完全产自尼加拉瓜的 puro 雪茄，1998年在欧洲面世，沿用了十九世纪一家哈瓦那工厂的名字，据 Cigar Coop 与 Blind Man''s Puff 2019年3月所述；Cigar Coop 当时称其在埃斯特利的 Joya de Nicaragua 卷制。德国零售商 Cigarworld.de 在2026年10月给出的是 H-2000 茄衣、Connecticut 茄套和茄芯，全部产自尼加拉瓜，属 longfiller。Villiger 把它列入其埃斯特利工厂（2021年9月底竣工）的品牌之中，另一家德国零售商 Noblego.de 在2026年10月有现货。","wrapper":"尼加拉瓜（H-2000）"},{"name":"Cuéllar","color":"#5C3317","story":"由三支多米尼加雪茄组成的系列，即 Connecticut Krēmē、Black Forest 与 Caribe，由 Jochy Blanco 在多米尼加共和国的工厂 Tabacalera Palma 生产，据 Cigar Coop 在2019年、2025年1月和2025年5月所述。Black Forest 于2019年10月宣布，茄衣为 maduro，茄套与茄芯均为多米尼加产；Caribe 于2025年1月31日宣布，茄衣为厄瓜多尔 habano，茄套与茄芯均为多米尼加产。2026年10月，Neptune Cigar 将 Caribe 作为现货销售，并称其由 Tabacalera La Palma 制造。","wrapper":"Connecticut、Maduro、Habano"},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"一个古巴老牌名，2007年由 Villiger 以多米尼加雪茄的身份重启，在 ABAM 卷制——据 Cigar Coop 2018年3月所述，这家位于圣多明各的工厂归 José「Matias」Maragoto 所有，负责卷制 Villiger 的多米尼加雪茄。","vitolas":[],"wrapper":"未公开"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"来自多米尼加共和国的系列，公司页面在2026年十月称其强度为轻至中等、价格实惠，在Villiger的等级表上为2级（共5级），共有五种规格：Perla、Corona、Robusto、Torpedo和Churchill。德国零售商Cigarworld.de称其在ABAM Cigars手工卷制，采用longfiller，以bundles形式销售，茄衣为厄瓜多尔Connecticut Shade，茄套来自印尼，茄芯为多米尼加共和国与尼加拉瓜的Piloto；据该零售商称，该品牌可追溯至2000年代初，该零售商自2010年十二月七日起将Corona收入目录。","vitolas":[],"wrapper":"Connecticut Shade（厄瓜多尔）"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"据Cigarworld.de称，该系列由Villiger于2014年发布；该零售商自2014年八月十二日起将其收入目录，称其手工卷制，采用mediumfiller，茄衣为厄瓜多尔H-2000，茄套来自印尼，茄芯来自尼加拉瓜。Villiger将其列入位于Estelí的工厂所产品牌之列，该工厂于2021年九月底竣工；2026年十月，公司页面列出五种产地为尼加拉瓜的规格（Perla、Corona、Robusto、Torpedo、Churchill），在其等级表上为4级（共5级）。","vitolas":[],"wrapper":"厄瓜多尔（H-2000）"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"该系列于2000年代初出现在德国的Liberty Cigar Company，后并入Villiger集团；它先离开洪都拉斯（Plasencia曾在那里卷制），再离开多米尼加共和国（ABAM曾在那里卷制），转至Estelí：一款新配方（茄衣为尼加拉瓜criollo，茄套来自多米尼加的Cibao，茄芯来自尼加拉瓜的Jalapa与Estelí）于2022年一月在Las Vegas的TPE展会上亮相，规格为Corona、Robusto和Gran Toro。2026年十月，公司页面将其列入手工制作雪茄之列，共四种规格（Gordito、Robusto、Corona、Gran Toro），在其等级表上为4级（共5级）。","vitolas":[],"wrapper":"Criollo（尼加拉瓜）"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"该系列于2025年以新配方重新推出，茄衣为厄瓜多尔Connecticut Shade，茄套来自尼加拉瓜，茄芯来自尼加拉瓜与多米尼加共和国，2025年四月在PCA展会上宣布，规格为Lonsdale（6 x 43）、Robusto（5 x 50）、Toro（6 x 50）和Churchill（7 x 50）；2026年七月的一篇报道称，此前的版本使用habano茄衣。Cigarworld.de称其在Estelí由Tabacalera Villiger de Nicaragua手工卷制，采用longfiller，在Joya de Nicaragua的场地内进行，并自2025年八月二十八日起将其收入目录；2026年十月，公司页面列出Robusto、Toro和Churchill，在其等级表上为2级（共5级）。","vitolas":[],"wrapper":"Connecticut（厄瓜多尔）"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"该系列于2017年五月在欧洲推出，有两个版本：洪都拉斯版（据一篇发布报道，由Nestor A. Plasencia在Danlí卷制）与多米尼加共和国版（据另一篇报道，在ABAM制作），规格为Robusto+（5 x 56）和Toro+（6 x 52）。2026年十月，公司页面将其列为四种产地：洪都拉斯、多米尼加共和国、尼加拉瓜和巴西，在其等级表上依次为4级、2.5级、5级和3.5级（共5级），并将其面向手工卷制雪茄的爱好者；Villiger将Corrida列入其位于Estelí的工厂所产品牌之列，该工厂于2021年九月底竣工。","vitolas":[],"wrapper":"未公开"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"该系列据Cigarworld.de称在Dortmund举行的InterTabac 2023上发布；该零售商称其在Estelí与Joya de Nicaragua合作手工卷制，采用longfiller，茄衣与茄芯来自尼加拉瓜，茄套来自印尼，并自2023年九月二十五日起将5 x 52规格收入目录。2026年十月，公司页面列出三种以尺寸命名的规格：4 x 56、5 x 52和6 x 54，在其等级表上为4级（共5级）；2013年四月的一篇预览报道已经以此名称介绍了一个使用三种茄衣的系列。","vitolas":[],"wrapper":"尼加拉瓜"}]',
  `gamme_ar` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"سيجار puro نيكاراغوي بالكامل صدر في أوروبا عام 1998، ويستعيد اسم مصنع هافاني من القرن التاسع عشر، بحسب Cigar Coop وBlind Man''s Puff في مارس 2019؛ وتقول Cigar Coop حينئذٍ إنه يُلفّ لدى Joya de Nicaragua في إستيلي. ويذكر Cigarworld.de، وهو تاجر تجزئة ألماني، في أكتوبر 2026 غلافًا H-2000 ورباطًا Connecticut وحشوة، كلّها من نيكاراغوا، من نوع longfiller. وتعدّه Villiger من علامات مصنعها في إستيلي، الذي اكتمل بناؤه في نهاية سبتمبر 2021، ويحتفظ به Noblego.de، وهو تاجر تجزئة ألماني آخر، في مخزونه في أكتوبر 2026.","wrapper":"نيكاراغوا (H-2000)"},{"name":"Cuéllar","color":"#5C3317","story":"سلسلة من ثلاث سيجارات دومينيكية، Connecticut Krēmē وBlack Forest وCaribe، تنتجها Tabacalera Palma، مصنع Jochy Blanco في جمهورية الدومينيكان، بحسب Cigar Coop في 2019 وفي يناير 2025 وفي مايو 2025. وBlack Forest، المعلن عنه في أكتوبر 2019، له غلاف maduro على رباط وحشوة دومينيكيين؛ وCaribe، المعلن عنه في 31 يناير 2025، له غلاف habano من الإكوادور على رباط وحشوة دومينيكيين. وفي أكتوبر 2026 يبيع Neptune Cigar الـCaribe بوصفه متوفرًا في المخزون، ويقول إنه صُنع لدى Tabacalera La Palma.","wrapper":"Connecticut وMaduro وHabano"},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"اسمُ علامة كوبية قديمة، أعادت Villiger إطلاقه سنة 2007 سيجارًا دومينيكيًّا، يُلفّ في ABAM، مصنع سانتو دومينغو الذي تقول Cigar Coop في مارس 2018 إنه مملوك لـJosé «Matias» Maragoto ومكلَّف بلفّ سيجارات Villiger الدومينيكية.","vitolas":[],"wrapper":"غير معلن"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","story":"خط من جمهورية الدومينيكان، تصفه صفحة الشركة في أكتوبر 2026 بأنه خفيف إلى متوسط وبسعر ميسور، عند المستوى 2 من 5 على سلّم Villiger، بخمسة مقاسات: Perla وCorona وRobusto وTorpedo وChurchill. ويذكر Cigarworld.de، وهو تاجر تجزئة ألماني، أنه ملفوف يدويًا من نوع longfiller لدى ABAM Cigars، ضمن bundles، بغلاف خارجي Connecticut Shade من إكوادور ورابط من إندونيسيا وحشوة Piloto من جمهورية الدومينيكان ومن نيكاراغوا؛ وتعود العلامة إلى مطلع سنوات 2000 بحسب هذا التاجر، الذي يُدرجها في فهرسه، بالنسبة إلى Corona، منذ 7 ديسمبر 2010.","vitolas":[],"wrapper":"Connecticut Shade (إكوادور)"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","story":"قُدّمت في 2014 على يد Villiger بحسب Cigarworld.de، الذي يُدرجها في فهرسه منذ 12 أغسطس 2014 ويقول إنها ملفوفة يدويًا من نوع mediumfiller، بغلاف خارجي H-2000 من إكوادور ورابط من إندونيسيا وحشوة من نيكاراغوا. وتعدّها Villiger من علامات مصنعها في Estelí، الذي اكتمل في أواخر سبتمبر 2021؛ وفي أكتوبر 2026 تذكر صفحة الشركة خمسة مقاسات من أصل نيكاراغوا (Perla وCorona وRobusto وTorpedo وChurchill)، عند المستوى 4 من 5 على سلّمها.","vitolas":[],"wrapper":"إكوادور (H-2000)"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","story":"ظهرت في مطلع سنوات 2000 لدى Liberty Cigar Company في ألمانيا، ثم انضمّت إلى مجموعة Villiger، وغادرت هندوراس، حيث كانت Plasencia تلفّها، ثم جمهورية الدومينيكان، حيث كانت ABAM تلفّها، إلى Estelí: مزيج جديد بغلاف خارجي criollo من نيكاراغوا ورابط من Cibao الدومينيكي وحشوة نيكاراغوية من Jalapa وEstelí عُرض في يناير 2022 في معرض TPE في Las Vegas بمقاسات Corona وRobusto وGran Toro. وفي أكتوبر 2026 تُدرجها صفحة الشركة ضمن سيجاراتها المصنوعة يدويًا، بأربعة مقاسات (Gordito وRobusto وCorona وGran Toro)، عند المستوى 4 من 5 على سلّمها.","vitolas":[],"wrapper":"Criollo (نيكاراغوا)"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","story":"أُعيد إطلاقها في 2025 بمزيج جديد، بغلاف خارجي Connecticut Shade من إكوادور ورابط من نيكاراغوا وحشوة من نيكاراغوا ومن جمهورية الدومينيكان، وأُعلن عنها في معرض PCA في أبريل 2025 بمقاسات Lonsdale (6 x 43) وRobusto (5 x 50) وToro (6 x 50) وChurchill (7 x 50)؛ وكانت النسخة السابقة بغلاف خارجي habano، بحسب تقرير في يوليو 2026. ويقول Cigarworld.de إنها ملفوفة يدويًا من نوع longfiller في Estelí لدى Tabacalera Villiger de Nicaragua، في مباني Joya de Nicaragua، ويُدرجها في فهرسه منذ 28 أغسطس 2025؛ وفي أكتوبر 2026 تذكر صفحة الشركة Robusto وToro وChurchill، عند المستوى 2 من 5 على سلّمها.","vitolas":[],"wrapper":"Connecticut (إكوادور)"},{"name":"Corrida","color":"#8B5A2B","force":null,"story":"أُطلقت في أوروبا في مايو 2017 بنسختين: هندوراس (ملفوفة في Danlí على يد Nestor A. Plasencia، بحسب تقرير عن الإطلاق) وجمهورية الدومينيكان (صُنعت لدى ABAM، بحسب تقرير آخر)، بمقاسي Robusto+ (5 x 56) وToro+ (6 x 52). وفي أكتوبر 2026 تعرضها صفحة الشركة بأربعة بلدان منشأ هي هندوراس وجمهورية الدومينيكان ونيكاراغوا والبرازيل، عند المستويات 4 و2,5 و5 و3,5 من 5 على سلّمها، وتوجّهها إلى هواة السيجار الملفوف يدويًا؛ وتعدّ Villiger علامة Corrida من علامات مصنعها في Estelí، الذي اكتمل في أواخر سبتمبر 2021.","vitolas":[],"wrapper":"غير معلن"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","story":"سلسلة قُدّمت في InterTabac 2023 في Dortmund بحسب Cigarworld.de، الذي يقول إنها ملفوفة يدويًا من نوع longfiller في Estelí بالشراكة مع Joya de Nicaragua، بغلاف خارجي وحشوة من نيكاراغوا ورابط من إندونيسيا، ويُدرجها في فهرسه منذ 25 سبتمبر 2023 للمقاس 5 x 52. وفي أكتوبر 2026 تذكر صفحة الشركة ثلاثة مقاسات مسمّاة بأبعادها: 4 x 56 و5 x 52 و6 x 54، عند المستوى 4 من 5 على سلّمها؛ وكان عرض تمهيدي في أبريل 2013 قد قدّم بالفعل تحت هذا الاسم خطًا بثلاثة أغلفة خارجية.","vitolas":[],"wrapper":"نيكاراغوا"}]',
  `source` = IF(LOCATE(CAST('roulée à l''ABAM, la fabrique de Villiger en République dominicaine' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'roulée à l''ABAM, la fabrique de Villiger en République dominicaine', 'roulée à l''ABAM, dite fabrique de Villiger par ces deux pages (non relues) ; ABAM, propriété de José Matias Maragoto d''après cigar-coop.com « Cigar News: Villiger Lounge Opens at ABAM Factory » (14 mars 2018)'), `source`),
  `source` = IF(LOCATE(CAST('cigarjournal.com « Villiger opened a brand new factory in Es' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarjournal.com « Villiger opened a brand new factory in Estelí » (10 novembre 2021 : coentreprise Villiger Group et Joya de Nicaragua, usine achevée fin septembre 2021) ; cigarslover.com « Villiger Cigars Opens New Nicaraguan Factory » (novembre 2021 : coentreprise avec Joya de Nicaragua, production depuis octobre 2021, usine de Feira de Santana conservée) ; premiumcigars.org « Breaking New Ground: Inside Villiger de Nicaragua » (24 juillet 2023 : usine dite détenue et exploitée par Villiger, supervisée par Joya, La Meridiana, La Vencedora et San''Doro produites depuis 2021) ; cigar-coop.com « PCA 2025: Villiger Cigars » (11 mai 2025 : la ligne Cuéllar est produite par Tabacalera Palma ; Villiger de Nicaragua, usine d''Estelí, fait 1888 Gran Reserva et La Capitana) ; cigar-coop.com « Cigar News: Villiger Cuéllar Caribe Announced » (31 janvier 2025 : Caribe produit à Tabacalera Palma, cape habano d''Équateur, liant et tripe dominicains) ; cigar-coop.com « Cigar News: Villiger to Release Cuellar Black Forest » (25 octobre 2019 : cape maduro, liant et tripe dominicains, Tabacalera Palma) ; neptunecigar.com « Villiger Cuellar Caribe Robusto 5 x 48 » (8 octobre 2026 : en stock, fait à Tabacalera La Palma, République dominicaine) ; cigar-coop.com « Cigar News: Villiger La Meridiana Coming to U.S. Market » (14 mars 2019 : puro nicaraguayen, Joya de Nicaragua, nom d''une fabrique havanaise) ; blindmanspuff.com « Cigar News: Villiger Debuts La Meridiana » (14 mars 2019 : sortie originale en 1998) ; cigarworld.de « Villiger La Meridiana Robusto » (8 octobre 2026 : cape H-2000, liant Connecticut, tripe du Nicaragua, au catalogue depuis le 15 septembre 2015, en vente) ; noblego.de « Villiger La Meridiana Robusto » (8 octobre 2026 : en stock, cape, liant et tripe du Nicaragua)')),
  `updated_at` = NOW()
 WHERE `name` = 'Villiger';

-- ── Warped ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('TABSA, dans la vallée de Jalapa, et El Titan de Bronze à Miami' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'TABSA, dans la vallée de Jalapa, et El Titan de Bronze à Miami', 'TABSA, à Estelí, et El Titan de Bronze à Miami'), `history`),
  `history_en` = IF(LOCATE(CAST('TABSA, in the Jalapa valley,' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'TABSA, in the Jalapa valley,', 'TABSA, in Estelí,'), `history_en`),
  `history_es` = IF(LOCATE(CAST('TABSA, en el valle de Jalapa,' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, 'TABSA, en el valle de Jalapa,', 'TABSA, en Estelí,'), `history_es`),
  `history_de` = IF(LOCATE(CAST('TABSA im Tal von Jalapa' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'TABSA im Tal von Jalapa', 'TABSA in Estelí'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('哈拉帕山谷的 TABSA' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '哈拉帕山谷的 TABSA', '埃斯特利的 TABSA'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('«تابسا» في وادي خالابا' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, '«تابسا» في وادي خالابا', 'TABSA في إستيلي'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Warped';

UPDATE `brands` SET
  `factory` = 'TABSA (Estelí, Nicaragua) et El Titan de Bronze (Miami)',
  `gamme` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","story":"Un nom de marque cubaine d''avant 1960, rempli d''un assemblage contemporain. Tabacs de Jalapa, formats fins, une longueur en bouche qui vient de la matière et non de la force.","vitolas":["Corona","Lancero"],"wrapper":"Corojo 99"},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","story":"Séries courtes, souvent annoncées sans préavis. Bois, foin, une pointe de poivre blanc — le registre que la maison défend contre la mode des gros modules.","vitolas":["Corona Gorda"],"wrapper":"Corojo 99"},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","story":"2016 — une collaboration avec Aganorsa, alors Casa Fernández, roulée chez eux : les bouledogues qui gardent les fermes, et des formats aux noms des chiens. Une ligne à deux maisons, pas une marque à part.","vitolas":[],"wrapper":"Corojo 99"},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","story":"Le cigare d''Edition One, société de Kyle Gellis et de son frère cadet Devin, fait chez TABSA (Tabacos Valle de Jalapa S.A., dite aussi Aganorsa Leaf par Cigar Wars et Neptune Cigar), avec du seul tabac Aganorsa, dit Cigar Dojo. Les dates divergent : lancé en douceur en 2016 puis connu à l''été 2017, dit Cigar Wars ; sorti début 2016, dit Cigar Dojo (10 novembre 2017) ; sorti en août 2017 après sa présentation à l''IPCPR 2017, dit Blind Man''s Puff (25 juillet 2018).","vitolas":[],"wrapper":"Corojo 99"}]',
  `gamme_en` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","story":"A pre-1960 Cuban brand name, filled with a contemporary blend. Jalapa tobaccos, slender formats, a length on the palate that comes from the material and not from strength.","vitolas":["Corona","Lancero"],"wrapper":"Corojo 99"},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","story":"Short series, often announced without warning. Wood, hay, a touch of white pepper — the register the house defends against the fashion for thick ring gauges.","vitolas":["Corona Gorda"],"wrapper":"Corojo 99"},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","story":"2016 — a collaboration with Aganorsa, then Casa Fernández, rolled at their factory: the bulldogs that guard the farms, and sizes named after the dogs. A two-house line, not a separate brand.","vitolas":[],"wrapper":"Corojo 99"},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","story":"The cigar of Edition One, the company of Kyle Gellis and his younger brother Devin, made at TABSA (Tabacos Valle de Jalapa S.A., also called Aganorsa Leaf by Cigar Wars and Neptune Cigar), with Aganorsa tobacco alone, says Cigar Dojo. The dates differ: soft-launched in 2016 then known in the summer of 2017, says Cigar Wars; released in early 2016, says Cigar Dojo (10 November 2017); released in August 2017 after its presentation at IPCPR 2017, says Blind Man''s Puff (25 July 2018).","vitolas":[],"wrapper":"Corojo 99"}]',
  `gamme_es` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","story":"Un nombre de marca cubana anterior a 1960, lleno de una liga contemporánea. Tabacos de Jalapa, formatos finos, una longitud en boca que viene de la materia y no de la fuerza.","vitolas":["Corona","Lancero"],"wrapper":"Corojo 99"},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","story":"Series cortas, a menudo anunciadas sin previo aviso. Madera, heno, una pizca de pimienta blanca — el registro que la casa defiende contra la moda de los cepos gruesos.","vitolas":["Corona Gorda"],"wrapper":"Corojo 99"},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","story":"2016 — una colaboración con Aganorsa, entonces Casa Fernández, liada en su fábrica: los bulldogs que guardan las fincas, y formatos con los nombres de los perros. Una línea de dos casas, no una marca aparte.","vitolas":[],"wrapper":"Corojo 99"},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","story":"El puro de Edition One, sociedad de Kyle Gellis y de su hermano menor Devin, hecho en TABSA (Tabacos Valle de Jalapa S.A., llamada también Aganorsa Leaf por Cigar Wars y Neptune Cigar), con tabaco exclusivamente Aganorsa, dice Cigar Dojo. Las fechas divergen: lanzado discretamente en 2016 y conocido en el verano de 2017, dice Cigar Wars; salido a principios de 2016, dice Cigar Dojo (10 de noviembre de 2017); salido en agosto de 2017 tras su presentación en la IPCPR 2017, dice Blind Man''s Puff (25 de julio de 2018).","vitolas":[],"wrapper":"Corojo 99"}]',
  `gamme_de` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","story":"Ein kubanischer Markenname von vor 1960, mit einem zeitgenössischen Blend gefüllt. Jalapa-Tabake, schlanke Formate, eine Länge am Gaumen, die aus der Substanz kommt und nicht aus der Kraft.","vitolas":["Corona","Lancero"],"wrapper":"Corojo 99"},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","story":"Kurze Serien, oft ohne Vorankündigung. Holz, Heu, ein Anflug weißer Pfeffer — das Register, das das Haus gegen die Mode dicker Ringmaße verteidigt.","vitolas":["Corona Gorda"],"wrapper":"Corojo 99"},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","story":"2016 — eine Zusammenarbeit mit Aganorsa, damals Casa Fernández, in deren Fabrik gerollt: die Bulldoggen, die die Farmen bewachen, und Formate mit den Namen der Hunde. Eine Linie zweier Häuser, keine eigene Marke.","vitolas":[],"wrapper":"Corojo 99"},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","story":"Die Zigarre von Edition One, der Firma von Kyle Gellis und seinem jüngeren Bruder Devin, gefertigt bei TABSA (Tabacos Valle de Jalapa S.A., von Cigar Wars und Neptune Cigar auch Aganorsa Leaf genannt), allein mit Aganorsa-Tabak, so Cigar Dojo. Die Daten weichen voneinander ab: leise 2016 gestartet und im Sommer 2017 bekannt geworden, so Cigar Wars; Anfang 2016 erschienen, so Cigar Dojo (10. November 2017); im August 2017 nach der Vorstellung auf der IPCPR 2017 erschienen, so Blind Man''s Puff (25. Juli 2018).","vitolas":[],"wrapper":"Corojo 99"}]',
  `gamme_zh` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","story":"一个1960年前的古巴品牌名，被填入当代配方。哈拉帕烟叶、细身尺寸，口中的绵长来自原料而非力度。","vitolas":["Corona","Lancero"],"wrapper":"Corojo 99"},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","story":"小批量系列，常常毫无预告地发布。木质、干草，一丝白胡椒——这正是这家逆着粗环径潮流所捍卫的路数。","vitolas":["Corona Gorda"],"wrapper":"Corojo 99"},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","story":"2016年——与 Aganorsa（当时叫 Casa Fernández）的合作，在对方工厂卷制：守护农场的斗牛犬，尺寸以狗的名字命名。两家公司的一条线，不是独立品牌。","vitolas":[],"wrapper":"Corojo 99"},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","story":"Edition One（Kyle Gellis 与其弟弟 Devin 的公司）的雪茄，在 TABSA（Tabacos Valle de Jalapa S.A.，Cigar Wars 与 Neptune Cigar 也称其为 Aganorsa Leaf）制造，据 Cigar Dojo 称仅使用 Aganorsa 的烟叶。日期说法不一：2016年低调推出，随后于2017年夏季为人所知，据 Cigar Wars；2016年初问世，据 Cigar Dojo（2017年11月10日）；2017年8月问世，此前已在 IPCPR 2017 上亮相，据 Blind Man''s Puff（2018年7月25日）。","vitolas":[],"wrapper":"Corojo 99"}]',
  `gamme_ar` = '[{"name":"La Colmena","color":"#A0522D","force":"Medium","story":"اسم علامة كوبية من قبل 1960، مملوء بخلطة معاصرة. تبغ خالابا ومقاسات نحيلة، وطول في الفم يأتي من المادة لا من القوّة.","vitolas":["Corona","Lancero"],"wrapper":"Corojo 99"},{"name":"Flor del Valle","color":"#8B7355","force":"Medium","story":"سلاسل قصيرة، غالباً بلا إعلان مسبق. خشب وقشّ ولمسة فلفل أبيض — المزاج الذي تدافع عنه الدار في وجه موضة الأقطار السميكة.","vitolas":["Corona Gorda"],"wrapper":"Corojo 99"},{"name":"Guardian of the Farm","color":"#4A3728","force":"Medium-Full","story":"2016 — تعاونٌ مع Aganorsa، التي كانت آنذاك Casa Fernández، يُلفّ في مصنعها: كلاب البولدوغ التي تحرس المزارع، وقياسات بأسماء الكلاب. خطٌّ لدارين، لا علامة مستقلّة.","vitolas":[],"wrapper":"Corojo 99"},{"name":"Cloud Hopper","color":"#3E4A6B","force":"Medium","story":"سيجار Edition One، شركة Kyle Gellis وأخيه Devin الذي يصغره سنًّا، صُنع لدى TABSA (Tabacos Valle de Jalapa S.A.، وتسمّيها Cigar Wars وNeptune Cigar أيضًا Aganorsa Leaf)، بتبغ Aganorsa وحده، بحسب Cigar Dojo. وتتباين التواريخ: أُطلق بهدوء في 2016 ثم عُرف في صيف 2017، بحسب Cigar Wars؛ وصدر في مطلع 2016، بحسب Cigar Dojo (10 نوفمبر 2017)؛ وصدر في أغسطس 2017 بعد عرضه في IPCPR 2017، بحسب Blind Man''s Puff (25 يوليو 2018).","vitolas":[],"wrapper":"Corojo 99"}]',
  `source` = IF(LOCATE(CAST('cigarwars.net « Aganorsa Leaf » (8 octobre 2026, sans date :' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarwars.net « Aganorsa Leaf » (8 octobre 2026, sans date : Aganorsa Leaf, ex Casa Fernández, alias Tabacos Valle de Jalapa S.A. et TABSA, à Estelí) ; cigardojo.com « Edition One Cloud Hopper No. 53 Review » (10 novembre 2017 : cigare sorti début 2016, mélange tout Aganorsa, fait par Tabacos Valle de Jalapa S.A., usine d''Estelí) ; blindmanspuff.com « Blind Cigar Review: Edition One | Cloud Hopper No. 53 » (25 juillet 2018 : montré à l''IPCPR 2017, sortie août 2017, tabac Aganorsa, TABSA à Estelí) ; warpedcigars.com « Cloud Hopper | Warped Cigars » (8 octobre 2026 : usine TABSA, blender Kyle Gellis, corps Medium, aucune mention d''Edition One ni d''Aganorsa) ; neptunecigar.com « Edition One Cloud Hopper No. 53 » (8 octobre 2026 : en stock, fait à la main au Nicaragua par Tabacos Valle de Jalapa S.A. alias TABSA et Aganorsa Leaf)')),
  `updated_at` = NOW()
 WHERE `name` = 'Warped';

-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Ashton' hote, 'history' champ
        UNION ALL SELECT 'Aging Room' hote, 'gamme' champ
        UNION ALL SELECT 'Aging Room' hote, 'history' champ
        UNION ALL SELECT 'CLE Cigar Company' hote, 'history' champ
        UNION ALL SELECT 'Foundation Cigar Company' hote, 'gamme' champ
        UNION ALL SELECT 'Foundation Cigar Company' hote, 'history' champ
        UNION ALL SELECT 'General Cigar' hote, 'gamme' champ
        UNION ALL SELECT 'General Cigar' hote, 'history' champ
        UNION ALL SELECT 'Miami Cigar & Co.' hote, 'gamme' champ
        UNION ALL SELECT 'Miami Cigar & Co.' hote, 'history' champ
        UNION ALL SELECT 'Ozgener Family Cigars' hote, 'gamme' champ
        UNION ALL SELECT 'Ozgener Family Cigars' hote, 'history' champ
        UNION ALL SELECT 'Tabacalera Palma' hote, 'gamme' champ
        UNION ALL SELECT 'Tabacalera Palma' hote, 'history' champ
        UNION ALL SELECT 'Tabacosta' hote, 'gamme' champ
        UNION ALL SELECT 'Tabacosta' hote, 'history' champ
        UNION ALL SELECT 'Villiger' hote, 'gamme' champ
        UNION ALL SELECT 'Warped' hote, 'gamme' champ
        UNION ALL SELECT 'Warped' hote, 'history' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

