-- ── Contrôle : chaque ligne doit valoir 1 ──
SELECT 'Ashton' AS hote, 'fr' AS lang, 'founded' AS quoi, (CAST(`founded` AS BINARY) = CAST('1985 — Philadelphie ; Robert Levin (Holt''s)' AS BINARY)) AS ok FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Tabacalera A. Fuente y Cía, Santiago (Rép. dominicaine) ; gamme San Cristobal : famille Garcia / My Father, Estelí (Nicaragua)' AS BINARY)) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('dans la boutique Holt''s Cigar Company, que la famille Levin tient depuis 1957 et que Robert Levin dirige depuis 1974, dit holts.com.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('dans une boutique spécialisée où William Ashton Taylor avait passé des années à vendre les cigares des autres et à développer une insatisfaction informée.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('the Holt''s Cigar Company shop, which the Levin family has kept since 1957 and which Robert Levin has run since 1974, says holts.com.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('a specialty tobacco shop where William Ashton Taylor had spent years selling other people''s premium cigars and developing an educated dissatisfaction with what was available at the price points his customers could sustain.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('la tienda Holt''s Cigar Company, que la familia Levin lleva desde 1957 y que Robert Levin dirige desde 1974, dice holts.com.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ashton'
UNION ALL SELECT 'Ashton', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('una tienda especializada donde William Ashton Taylor había pasado años vendiendo los puros de los demás y desarrollando una insatisfacción informada.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Ashton'
