UNION ALL SELECT 'Miami Cigar & Co.', 'zh', 'gamme Nestor Miranda Collection (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_zh`, '$[0].story')) AS BINARY) = CAST('以创始人命名的系列，据 Cigar Coop 所述，2014年推出，在埃斯特利的 My Father 制作——本词条归类的依据。该品牌的 Grand Reserve 2024 也在那里卷制（My Father Cigars S.A.，2025年6月）；2026年3月宣布的 Private Reserve Lancero 则在多米尼加共和国的 La Aurora 卷制。' AS BINARY)) FROM `brands` WHERE `name` = 'Miami Cigar & Co.'
