UNION ALL SELECT 'Ozgener Family Cigars', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Bosphorus, anunciado en junio de 2022, fue liado primero en Estelí, en Luciano, antes Tabacalera Pichardo — la fábrica de Eradio Pichardo cuya ficha lleva este atlas —, y confiado después, en noviembre de 2022, a Tabacalera La Alianza, la fábrica de E.P. Carrillo en la República Dominicana, rebautizada Casa Carrillo en 2024, donde se lían también Aramas, segunda línea, anunciada en marzo de 2023 y nombrada por el monte Ararat, y Firsat, en 2024. Karatoba (2025) viene de NACSA, en Estelí; Maracana (marzo de 2026), de My Father en Honduras; la edición limitada World Cup 2026, de My Father en Nicaragua. La ficha sigue clasificada en Nicaragua, pero tres de las cinco líneas actuales salen de la República Dominicana.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
