UNION ALL SELECT 'Ozgener Family Cigars', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Bosphorus, im Juni 2022 angekündigt, wurde zuerst in Estelí bei Luciano gerollt, früher Tabacalera Pichardo — der Fabrik von Eradio Pichardo, deren Eintrag dieser Atlas führt —, dann im November 2022 Tabacalera La Alianza anvertraut, der Fabrik von E.P. Carrillo in der Dominikanischen Republik, 2024 in Casa Carrillo umbenannt, wo auch Aramas, die zweite Linie (im März 2023 angekündigt, nach dem Berg Ararat benannt), und Firsat (2024) gerollt werden. Karatoba (2025) kommt von NACSA in Estelí; Maracana (März 2026) von My Father in Honduras; die limitierte Edition World Cup 2026 von My Father in Nicaragua. Der Eintrag bleibt in Nicaragua eingeordnet, aber drei der fünf laufenden Linien kommen aus der Dominikanischen Republik.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
