UNION ALL SELECT 'Ozgener Family Cigars', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('أُعلن عن Bosphorus في حزيران/يونيو 2022، ولُفّ أولًا في إستيلي لدى Luciano، المعروف سابقًا باسم Tabacalera Pichardo — وهو مصنع إراديو بيتشاردو الذي يحمل هذا الأطلس بطاقته —، ثم أُوكل في تشرين الثاني/نوفمبر 2022 إلى Tabacalera La Alianza، مصنع E.P. Carrillo في جمهورية الدومينيكان، الذي أُعيدت تسميته Casa Carrillo في 2024، وفيه يُلفّ أيضًا Aramas، الخطّ الثاني، المعلن عنه في آذار/مارس 2023 والمسمّى على جبل أرارات، وFirsat في 2024. ويأتي Karatoba (2025) من NACSA في إستيلي؛ وMaracana (آذار/مارس 2026) من My Father في هندوراس؛ والإصدار المحدود World Cup 2026 من My Father في نيكاراغوا. وتبقى البطاقة مصنّفة في نيكاراغوا، لكنّ ثلاثة من الخطوط الخمسة الجارية تخرج من جمهورية الدومينيكان.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Ozgener Family Cigars'
