UNION ALL SELECT 'Warped', 'fr', 'gamme Cloud Hopper (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme`, '$[3].story')) AS BINARY) = CAST('Le cigare d''Edition One, société de Kyle Gellis et de son frère cadet Devin, fait chez TABSA (Tabacos Valle de Jalapa S.A., dite aussi Aganorsa Leaf par Cigar Wars et Neptune Cigar), avec du seul tabac Aganorsa, dit Cigar Dojo. Les dates divergent : lancé en douceur en 2016 puis connu à l''été 2017, dit Cigar Wars ; sorti début 2016, dit Cigar Dojo (10 novembre 2017) ; sorti en août 2017 après sa présentation à l''IPCPR 2017, dit Blind Man''s Puff (25 juillet 2018).' AS BINARY)) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'en', 'gamme Cloud Hopper', (JSON_CONTAINS(JSON_EXTRACT(`gamme_en`, '$[*].name'), '"Cloud Hopper"')) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'en', 'gamme Cloud Hopper (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_en`, '$[3].story')) AS BINARY) = CAST('The cigar of Edition One, the company of Kyle Gellis and his younger brother Devin, made at TABSA (Tabacos Valle de Jalapa S.A., also called Aganorsa Leaf by Cigar Wars and Neptune Cigar), with Aganorsa tobacco alone, says Cigar Dojo. The dates differ: soft-launched in 2016 then known in the summer of 2017, says Cigar Wars; released in early 2016, says Cigar Dojo (10 November 2017); released in August 2017 after its presentation at IPCPR 2017, says Blind Man''s Puff (25 July 2018).' AS BINARY)) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'es', 'gamme Cloud Hopper', (JSON_CONTAINS(JSON_EXTRACT(`gamme_es`, '$[*].name'), '"Cloud Hopper"')) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'es', 'gamme Cloud Hopper (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_es`, '$[3].story')) AS BINARY) = CAST('El puro de Edition One, sociedad de Kyle Gellis y de su hermano menor Devin, hecho en TABSA (Tabacos Valle de Jalapa S.A., llamada también Aganorsa Leaf por Cigar Wars y Neptune Cigar), con tabaco exclusivamente Aganorsa, dice Cigar Dojo. Las fechas divergen: lanzado discretamente en 2016 y conocido en el verano de 2017, dice Cigar Wars; salido a principios de 2016, dice Cigar Dojo (10 de noviembre de 2017); salido en agosto de 2017 tras su presentación en la IPCPR 2017, dice Blind Man''s Puff (25 de julio de 2018).' AS BINARY)) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'de', 'gamme Cloud Hopper', (JSON_CONTAINS(JSON_EXTRACT(`gamme_de`, '$[*].name'), '"Cloud Hopper"')) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'de', 'gamme Cloud Hopper (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_de`, '$[3].story')) AS BINARY) = CAST('Die Zigarre von Edition One, der Firma von Kyle Gellis und seinem jüngeren Bruder Devin, gefertigt bei TABSA (Tabacos Valle de Jalapa S.A., von Cigar Wars und Neptune Cigar auch Aganorsa Leaf genannt), allein mit Aganorsa-Tabak, so Cigar Dojo. Die Daten weichen voneinander ab: leise 2016 gestartet und im Sommer 2017 bekannt geworden, so Cigar Wars; Anfang 2016 erschienen, so Cigar Dojo (10. November 2017); im August 2017 nach der Vorstellung auf der IPCPR 2017 erschienen, so Blind Man''s Puff (25. Juli 2018).' AS BINARY)) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'zh', 'gamme Cloud Hopper', (JSON_CONTAINS(JSON_EXTRACT(`gamme_zh`, '$[*].name'), '"Cloud Hopper"')) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'zh', 'gamme Cloud Hopper (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_zh`, '$[3].story')) AS BINARY) = CAST('Edition One（Kyle Gellis 与其弟弟 Devin 的公司）的雪茄，在 TABSA（Tabacos Valle de Jalapa S.A.，Cigar Wars 与 Neptune Cigar 也称其为 Aganorsa Leaf）制造，据 Cigar Dojo 称仅使用 Aganorsa 的烟叶。日期说法不一：2016年低调推出，随后于2017年夏季为人所知，据 Cigar Wars；2016年初问世，据 Cigar Dojo（2017年11月10日）；2017年8月问世，此前已在 IPCPR 2017 上亮相，据 Blind Man''s Puff（2018年7月25日）。' AS BINARY)) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'ar', 'gamme Cloud Hopper', (JSON_CONTAINS(JSON_EXTRACT(`gamme_ar`, '$[*].name'), '"Cloud Hopper"')) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'ar', 'gamme Cloud Hopper (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_ar`, '$[3].story')) AS BINARY) = CAST('سيجار Edition One، شركة Kyle Gellis وأخيه Devin الذي يصغره سنًّا، صُنع لدى TABSA (Tabacos Valle de Jalapa S.A.، وتسمّيها Cigar Wars وNeptune Cigar أيضًا Aganorsa Leaf)، بتبغ Aganorsa وحده، بحسب Cigar Dojo. وتتباين التواريخ: أُطلق بهدوء في 2016 ثم عُرف في صيف 2017، بحسب Cigar Wars؛ وصدر في مطلع 2016، بحسب Cigar Dojo (10 نوفمبر 2017)؛ وصدر في أغسطس 2017 بعد عرضه في IPCPR 2017، بحسب Blind Man''s Puff (25 يوليو 2018).' AS BINARY)) FROM `brands` WHERE `name` = 'Warped'
UNION ALL SELECT 'Warped', 'fr', 'source', (LOCATE(CAST('cigarwars.net « Aganorsa Leaf » (8 octobre 2026, sans date :' AS BINARY), CAST(`source` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Warped';
SELECT (SELECT COUNT(*) FROM `translation_status` t JOIN `brands` b ON b.`name` = t.`entite_id` AND t.`entite` = 'brands'
         WHERE t.`source_hash` <> SHA1(CASE t.`champ` WHEN 'history' THEN b.`history` ELSE b.`gamme` END)
           AND t.`champ` IN ('history', 'gamme') AND b.`name` IN ('Ashton','Aging Room','CLE Cigar Company','Foundation Cigar Company','General Cigar','Miami Cigar & Co.','Ozgener Family Cigars','Rocky Patel','Tabacalera Palma','Tabacosta','Villiger','Warped')) = 0 AS sceaux_a_jour,
       (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 256') AS journal_non_tronque;
